\begin{theorem}\label{thm:main}
Assume the continuum hypothesis. There is an abstract elementary class
\(K\) in a countable finitary relational language such that
\begin{enumerate}[label=\textup{(\roman*)}]
 \item \(\LS(K)=\aleph_0\);
 \item \(K\) has at least two nonisomorphic models of cardinality
       \(\beth_{\omega_2}=H(K)\);
 \item putting \(\Lambda=\beth_{(2^{\aleph_1})^+}\),
       the class \(K\) is categorical in every cardinal
       \(\mu\ge\Lambda\).
\end{enumerate}
In particular, \(\lambda=\Lambda^+>H(K)\) is a categoricity cardinal
from which downward transfer to \(H(K)\) fails.
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a three-dimensional complete Noetherian normal local domain
$R$ containing $\C$, with residue field $\C$, such that no nonzero finitely
generated $R$-module has depth three.
\end{theorem}

\begin{theorem}[Recovery at a point with full Hodge group]\label{main:generic}
Suppose $\operatorname{Hg}(V)=\operatorname{SO}(V,q)$. The following conditions are equivalent.
\begin{enumerate}
\item There are an abelian variety $B$ and a cycle $\alpha\in\operatorname{CH}^2(S\times B)_{\mathbb Q}$ such that
\[
 \alpha_*:V\longrightarrow H^2(B,\mathbb Q)
\]
is nonzero.
\item There are a smooth connected projective surface $Y$ and a dominant generically finite morphism $f:Y\to S$ such that
\begin{equation}\label{eq:wedge-condition}
 f_*\!\left(\operatorname{im}\!\left[
 \bigwedge\nolimits^2 H^0(Y,\Omega_Y^1)
 \longrightarrow H^0(Y,\Omega_Y^2)\right]\right)\ne0.
\end{equation}
\item The prescribed full Kuga--Satake map is realized as in \eqref{eq:cycle-target}, for any stipulated standard data on $T$.
\end{enumerate}
In this situation $T=V$. The same input realizes the standard map for the full primitive Clifford construction with the cup form.
\end{theorem}

\begin{theorem}[Specialization in a polarized component]\label{main:specialization}
Fix a component of the moduli space of primitively amply polarized K3 surfaces of degree $2d$. Assume that condition \textup{(i)} or condition \textup{(ii)} of Theorem~\ref{main:generic} holds very generally in that component. Then every $(S,h)$ in the component satisfies \eqref{eq:cycle-target}, with all the stipulated standard data on $T(S)$.

Here it suffices that, about each desired point, the input holds outside a countable union of proper closed analytic subsets of a full polarized period chart. In particular an input outside countably many proper algebraic subsets of the moduli component suffices. The witness cycles, abelian varieties, or surface covers need not vary in a family.
\end{theorem}

\begin{theorem}
\label{thm:main}
There exist a finite field $K$ of characteristic two, a finitely presented group $G$ containing an element of odd prime order, and elements $a_{\mathrm{out}},b_{\mathrm{out}}\in K[G]$ such that
\[
a_{\mathrm{out}}b_{\mathrm{out}}=1,
\qquad b_{\mathrm{out}}a_{\mathrm{out}}\ne1.
\]
The field, group, and finite sums are specified by a terminating prescription involving finite sets and finite-field arithmetic.
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed $\alpha$ with $\GW<\alpha\le1$, it is NP-hard to approximate
Max-Cut within a factor of $\alpha$. This holds for simple unweighted graphs.
\end{theorem}

\begin{theorem}\label{thm:fock}
For every \(0<\gamma<\gamma_*\), there is an integer \(Q_\gamma\) such that
for every integer \(Q\ge Q_\gamma\),
\begin{equation}\label{eq:architecture}
 H_Q^2\ge\gamma H_Q\qquad\text{on }\FF_Q.
\end{equation}
The threshold \(Q_\gamma\) is independent of particle number.
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed integer \(k\ge3\), there is a constant
\(\alpha_k\in(0,\infty)\) such that, for independent proper uniformly
signed \(k\)-clauses sampled with replacement,
\[
 \lim_{n\to\infty}P_n(\lfloor cn\rfloor)
 =
 \begin{cases}
  1,&0\le c<\alpha_k,\\
  0,&c>\alpha_k.
 \end{cases}
\]
\end{theorem}

\begin{theorem}[Cannon's conjecture]
\label{thm:main}
Let $G$ be a hyperbolic group with $\partial G$ homeomorphic to $\Sphere$.
There is a homomorphism $\rho:G\to\Isom(\HH^3)$ for which the action
on $\HH^3$ is proper and cocompact. Its kernel is finite.
\end{theorem}

\begin{theorem}\label{thm:main}
The optimal power is $\alpha_{\mathrm{tot}}=4$.
More precisely, $\R(f)=O((1+\Q(f))^4)$ for every total Boolean function.
For each fixed integer $k\ge2$, there are positive constants $c_k,C_k,b_k$
and total Boolean functions $F_{k,m}$, for all sufficiently large powers
of four $m$, such that
\begin{equation}\label{eq:main-family}
 \Q(F_{k,m})\le C_k\sqrt m\,(\log m)^{b_k},
 \qquad
 \R(F_{k,m})\ge c_k\frac{m^{2-1/k}}{(\log m)^2}.
\end{equation}
\end{theorem}

\begin{theorem}\label{main:group}
There exists a finite lattice that is not isomorphic to $[D,G]$ for any
subgroup $D$ of any finite group $G$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a deterministic algorithm, polynomial in the total encoded input size, that on every finite collection $\mathcal S$ of explicitly represented ordinary strings outputs a common superstring $T$ satisfying
\[
\len{T}\le 2\OPT(\mathcal S).
\]
\end{theorem}

\begin{theorem}[Friedgut--Kalai sharp-threshold conjecture]
\label{thm:threshold}
For every integer $n\ge2$, every nontrivial increasing family $\mathcal P$ of graphs on $n$ vertices invariant under all vertex permutations, and every $0<\varepsilon<1/2$,
\begin{equation}
\label{eq:threshold}
 p_{1-\varepsilon}(\mathcal P)-p_\varepsilon(\mathcal P)
 \le \frac{2^{19}}{(\log n)^2}\log\frac1{2\varepsilon}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a closed connected orientable smooth three-manifold $M$ with a $C^\infty$ Riemannian metric without conjugate points, such that $M$ admits no $C^\infty$ Riemannian metric whose sectional curvature is everywhere at most zero.
\end{theorem}

\begin{theorem}
\label{thm:main}
There exist a finitely generated torsion-free discrete group \(\Gproj\)
and a projection \(e\in C_r^*(\Gproj)\) such that
\[
 0<\tau_{\Gproj}(e)<\frac12.
\]
In particular, \(e\) is neither zero nor the identity.
\end{theorem}

\begin{theorem}[Geometric conclusion]
\label{geo:main}
There are absolute constants $C_*,C_\bullet$ such that, for sufficiently
large $\ell$, the preceding hypotheses have the following consequences.
Every component map $\phi:C\to X$ is an embedding.  Index copies by pairs
$(C,\phi)$ modulo the equivalence
\[
 (C,\phi)\sim
 (\delta_a C,\phi\delta_a^{-1}),\qquad a\in F.
\]
Thus an indexed copy $Q$ remembers its source component and source vertices
up to this deck alignment, in addition to its embedded image.
There is a well-order of these copies and an induced intrinsic ball $B(Q)$
in each $Q$ such that
\begin{enumerate}
 \item every vertex of $Q$ shared with an earlier copy belongs to $B(Q)$;
 \item the subgraph of $Q$ consisting of all edges with at least one
 endpoint in $B(Q)$ is a forest;
 \item for every vertex of $B(Q)$ lying over layer $i$,
 \begin{equation}
 |V(B(Q))|\le\mathfrak w_i,
 \qquad \mathfrak w_i=2^{C_\bullet H_i};
 \label{geo:weight}
 \end{equation}
 \item if $D_Q$ is $V(Q)$ minus its vertices shared with earlier copies,
 the domains $D_Q$ are pairwise disjoint, and deleting every edge of $Q$
 whose two endpoints lie in $D_Q$, for all $Q$, leaves a forest in $X$.
\end{enumerate}
Furthermore $\Gbase$ is torsion-free.  None of the constants depends on
$F$, the voltage values, the number of components of $P$, or $|S|$.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist a finitely presented torsion-free group \(G\) and nonzero elements
\(\alpha,\beta\in\mathbb F_2[G]\) such that \(\alpha\beta=0\).
Moreover, \(G\) admits a finite two-dimensional classifying space.
\end{theorem}

\begin{theorem}\label{thm:main}
For the Hamiltonian \eqref{eq:target}, with the spin normalization above,
\[
 E_1(L,3/5)-E_0(L,3/5)>\frac{\log 10}{392}
 \qquad\text{for every integer }L\ge960.
\]
\end{theorem}

\begin{theorem}[Classification]\label{thm:classification}
Let $A=\{a_1,\ldots,a_s\}\subset\R^d$ be a finite set of at least two
points with affine span $\R^d$, and define $p_i,F,B,m_F$ as above.
Then $A$ is Ramsey if and only if there is a matrix
$P\in\operatorname{Mat}_{d+1}(B)$ such that
\begin{align}
 (p_i\otimes1)^T P(1\otimes p_i)&=0
       &&(1\le i\le s),\label{eq:field-evaluations}\\
 m_F(P_{\alpha\beta})&=\delta_{\alpha\beta}
       &&(1\le\alpha,\beta\le d).\label{eq:field-spatial}
\end{align}
Here the entries of $p_i\otimes1$ and $1\otimes p_i$ are formed
componentwise. There are no separate conditions on the multiplied
constant row or constant column of $P$.
\end{theorem}

\begin{theorem}\label{thm:main}
Assume Assumption~\ref{ass:manifold}. Let $X$ be a connected smooth projective complex fourfold and let $D\subset X$ be a nonempty smooth connected reduced divisor. If $\sqrt[2]{(X,D)}$ is special, then
\begin{equation}\label{eq:target-group}
 G=\pi_1(X\setminus D,x)\big/\langle\!\langle\gamma^2\rangle\!\rangle
\end{equation}
contains an abelian subgroup of finite index. Here $\gamma$ is a positively oriented meridian about $D$, transported to $x\in X\setminus D$.
\end{theorem}

\begin{theorem}
\label{thm:main}
There exist a separable unital complex \(C^*\)-algebra \(A\), admitting
a normalized \(2\)-quasitrace, and positive contractions \(a,b\in A\)
such that every normalized \(2\)-quasitrace \(\tau\) on \(A\) satisfies
\[
 \tau(a+b)-\tau(a)-\tau(b)\ge\frac1{144}.
\]
\end{theorem}

\begin{theorem}\label{na:main}
There exists a unital infinite-dimensional simple complex $C^*$-algebra
$A$ with a faithful tracial state such that all its nonzero irreducible
representations are unitarily equivalent. In particular, $A$ is not
isomorphic to $K(H)$ for any complex Hilbert space $H$.
\end{theorem}

\begin{theorem}\label{thm:main}
For some sufficiently large even integer $N$, the manifold
$Q=S^9\times S^{N-1}$ admits a closed exact smoothly embedded Lagrangian
$L\subset T^*Q$ such that $L$ is diffeomorphic to $Q$ and no compactly
supported Hamiltonian isotopy carries the zero section to $L$.
\end{theorem}

\begin{theorem}
\label{thm:main}
There exist absolute constants $c>0$ and $m_0$ such that, for every integer
$m\ge m_0$,
\[
 \bdc(\per_m)\ge c m^3.
\]
One may take $c=1/(5\,529\,600e)$ and $m_0=1408$.
\end{theorem}

\begin{theorem}\label{thm:counterexample}
There is a smooth Hamiltonian diffeomorphism $\phi$ of the closed connected
symplectic six-manifold $Q^3$ such that
\begin{equation}\label{eq:counterexample}
 \#\Fix(\phi)=3<4=\Crit(Q^3)
                  =\operatorname{cuplength}(Q^3;\mathbb Q).
\end{equation}
At least one fixed point of $\phi$ is degenerate.
\end{theorem}

\begin{theorem}\label{thm:main}
For every pair of positive integers $n,m$, every $A\in M_n(\C)$,
every nonnegative integer $d$, and every polynomial
$P(z)=\sum_{k=0}^d B_kz^k$ with $B_k\in M_m(\C)$,
\begin{equation}\label{eq:main}
 \|P[A]\|\le2\max_{z\in W(A)}\|P(z)\|.
\end{equation}
The constant two cannot be decreased uniformly over $n,m$, and $d$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a fixed subset $S$ of real $\ell_2$, equipped with its induced Hilbert distance, whose doubling constant is at most $76800$ and which admits no bi-Lipschitz embedding into $\R^k$ for any positive integer $k$, at any finite distortion.
\end{theorem}

\begin{theorem}
\label{thm:main}
There is a finitely generated residually finite group $G$ such that
\[
 \cdim G=2,\qquad \gdim G=3.
\]
One may take $G$ to be the height kernel in the right-angled Artin group associated to a finite acyclic flag triangulation of the presentation complex
\begin{equation}
\label{eq:seed-presentation-intro}
 \langle x,y\mid x^2=y^5,\ x^2=(xy^{-1})^3\rangle.
\end{equation}
No two-dimensional classifying space for this $G$ exists, regardless of the number of its cells.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist a finite connected two-dimensional aspherical simplicial complex $K$ and a constant $C<\infty$ with the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item Every combinatorial edge loop of length $\ell$ in the universal cover of $K$ bounds a disk diagram with at most $C\ell$ triangular faces.
\item The group $\pi_1K$ admits no geometric action on a proper complete $\CAT(0)$ space.
\end{enumerate}
In particular, $\pi_1K$ is word-hyperbolic, and no finite simplicial complex homotopy equivalent to $K$ admits a locally $\CAT(0)$ geodesic length metric inducing its given topology. Consequently, no such model admits a compatible locally $\CAT(-1)$ geodesic length metric.
\end{theorem}

\begin{theorem}\label{thm:main}
There is an absolute constant \(C>0\) such that, for every finite
simple undirected graph \(G\) with \(n\) vertices, \(E(G)\) has a
partition into at most \(Cn\) parts, each of which is the edge set of
a cycle or consists of a single edge.
\end{theorem}

\begin{theorem}[Uniform representing densities]\label{density:main}
There is a constant $K_*>0$, depending only on the fixed profiles
$f,b$ and $R_0$, with the following property.  For every fixed
$D_0>\max\{1,2\sqrt{2R_0}\}$ there is an integer threshold $Q_0$
such that, for every integer $Q\ge Q_0$ and every choice of the
separated sets above, the recursion \eqref{density:recursion}
has the following properties for all $j\ge1$:
\begin{enumerate}
\item $W_j$ is smooth and strictly positive, and $W_j\,d\sigma$
represents holomorphic evaluation at zero.  In particular it is
a probability measure.
\item Under global phase rotation, $W_j$ has frequencies only
between $-\ell_j$ and $\ell_j$, and its mean on every phase orbit
is exactly one.
\item At every point of $S$,
\begin{equation}\label{density:uniform-bounds}
 \begin{gathered}
 c_0W_{j-1}\le W_j\le2W_{j-1},\\
 |ZW_j|\le K_*\sqrt{k_j}\,W_j,
 \qquad |TW_j|\le K_*k_jW_j
 \end{gathered}
\end{equation}
for every unit horizontal vector $Z$.
\end{enumerate}
The threshold $Q_0$ may also be enlarged to impose any fixed lower
threshold on the degrees $k_j$.
\end{theorem}

\begin{theorem}\label{thm:main}
The compact set
\[
 X=\{uu^{\mathsf T}:u\in\mathbb R^4,\ \|u\|=1\}
 \subset\{A\in\operatorname{Sym}_4(\mathbb R):\operatorname{tr}A=1\},
\]
with the Frobenius metric, has diameter $\sqrt2$ and cannot be covered
by ten subsets of diameter strictly less than $\sqrt2$.
\end{theorem}

\begin{theorem}[Hierarchy bound for the metric test cone]
\label{thm:tg-hierarchy}
There is an absolute integer $h_0$ such that, for every integer
$h\ge h_0$, every locally $h$-connected hierarchy of $G$, and every
collection $\mathcal M$ of nonroot nodes satisfying
$|O(A)|\ge |P(A)|/h$, there is a matrix $D\succ0$ on $\mathsf E$ with
\begin{align}
 \ip{D}{Z}&\le\ip{L_G}{Z} &&(Z\in\mathcal N),\label{tg:shortcut}\\
 \frac1{|O(A)|}\sum_{e\in O(A)}b_e^TD^{-1}b_e
 &\le h^{-31/40} &&(A\in\mathcal M).\label{tg:hierarchy-resistance}
\end{align}
The cutoff is independent of the graph and the hierarchy depth.
\end{theorem}

\begin{theorem}\label{intro:main}
There are absolute constants $\eta,c_1>0$ and an integer $n_0\ge3$ such that
\[
 \Delta(n)\ge c_1n^{-2+\eta}
 \qquad\text{for every integer }n\ge n_0.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
There are absolute constants \(0<C<\infty\) and \(1\le\beta<4/3\) such that
\(u(n)\le Cn^\beta\) for every nonnegative integer \(n\).
\end{theorem}

\begin{theorem}\label{thm:counterexample}
Let \(T_{10}=\conv(0,e_1,\ldots,e_{10})\subset\R^{10}\), where the
\(e_i\) are the coordinate unit vectors, and let
\(K=T_{10}\times T_{10}\subset\R^{20}\). Then
\[
 \frac{R_{20}(K)}{c_{20}}
 =\frac{121\binom{20}{10}}{21\cdot2^{20}}
 =\frac{22\,355\,476}{22\,020\,096}>1.
\]
Thus \(K\) violates \eqref{eq:proposed-bound} in dimension twenty.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist a smooth connected projective complex fourfold $X$ and a
simple abelian surface $A\subset X$ such that
\begin{enumerate}
\item $X$ has large fundamental group;
\item $\im\bigl(\pi_1(A)\to\pi_1(X)\bigr)\simeq\Z$.
\end{enumerate}
The universal cover $\widetilde X$ contains no positive-dimensional
compact complex analytic subvariety and is not Stein.
\end{theorem}

\begin{theorem}\label{thm:main}
Every nonempty finite oriented graph has a vertex \(v\) such that
\[
 \abs{N_1^+(v)}\leq \abs{N_2^+(v)}.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
There is an absolute constant $C>0$ such that
\[
 h(k)\le C\frac{k^2}{(\log\log(3k))^2}
 \qquad\text{for every integer }k\ge1.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For every prime \(p\geq5\), the canonical map
\begin{equation}\label{eq:main-map}
 \tau_{L_{K(3)}S}:L_0L_{K(3)}S\longrightarrow
                         L_0L_{K(2)}L_{K(3)}S
\end{equation}
is nonzero on \(\pi_{-3}\).
\end{theorem}

\begin{theorem}[Sharp Fourier certificate]\label{intro:main}
There is a real radial Schwartz function $f:\RR^2\to\RR$ such that
\begin{equation}\label{intro:conditions}
  \widehat f(0)=1,\qquad f(0)=\frac{2}{\sqrt3},\qquad
  \widehat f(\xi)\ge0\quad(\xi\in\RR^2),\qquad
  f(x)\le0\quad(|x|\ge1).
\end{equation}
\end{theorem}

\begin{theorem}[The simplex inequality]\label{intro:simplex}
For every integer $n\ge1$, every convex body $K\subset\R^n$ satisfies
the following bound, with equality if and only if $K$ is a simplex:
\begin{equation}\label{intro:simplex-bound}
 L_K\le
 \frac{(n!)^{1/n}}{(n+1)^{(n+1)/(2n)}\sqrt{n+2}}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There exist a $C^\infty$ volume-preserving diffeomorphism
$T\colon\T^3\to\T^3$ and a real function $f\in L^2_0(\T^3,\mu)$ such that
\[
                  \{f\circ T^n:n\in\Z\}
\]
is an orthonormal basis of $L^2_0(\T^3,\mu)$.
Consequently $T$ is ergodic, and $U_T$ on this space is unitarily equivalent
to multiplication by the coordinate $w$ on $L^2(S^1,m)$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a finite constant $C_\beta$, depending only on $\beta$, such that
\[
 \Prob_J\left\{\Var_{\mu_0}(f)\le C_\beta\D_0(f)
       \text{ for every }f:\{-1,1\}^n\longrightarrow\R\right\}
 \longrightarrow1.
\]
Consequently, the discrete-time heat-bath chain that chooses a uniform site
has spectral gap at least $1/(C_\beta n)$ with probability tending to one.
\end{theorem}

\begin{theorem}\label{thm:main}
In $R=\C[x_1,x_2,x_3,x_4]$, put
\begin{equation}\label{eq:explicit-counterexample}
 Q=x_2^2-x_4^2+x_1x_3,
 \qquad
 f=x_1-2Q\bigl(Q(x_2+x_4)+x_1x_4\bigr).
\end{equation}
There is a $\C$-algebra automorphism of $R[w]$ sending $f$ to $x_1$, but there is no such automorphism of $R$.
\end{theorem}

\begin{theorem}[Uniform inverse-first-power bound]\label{thm:main}
There exist constants \(0<\varepsilon<1/4\) and \(C<\infty\) such that
\begin{equation}\label{eq:uniform}
 M_{-1}[f'](r)\le C(1-r)^{-1/4+\varepsilon}
 \qquad\text{for every }f\in\SSS\text{ and every }1/2\le r<1.
\end{equation}
Consequently \(B_b(-1)<1/4\), and Kraetzer's conjectured identity
\eqref{eq:kraetzer} is false.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a finite nonempty set $T\subset\Z^3$ such that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $T$ tiles $\Z^3$ by translations, but no translation set $A$ with $A\oplus T=\Z^3$ is invariant under a subgroup of finite index in $\Z^3$;
\item the set $\Omega=T+[0,1]^3$ tiles $\R^3$ by translations up to null sets, but no such tiling has a translation set invariant under a lattice of full rank in $\R^3$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Mixing from a typical Gibbs state]\label{thm:main}
For every fixed $\beta>1$, there is $c_\beta\in(0,1)$ such that
\[
 \mathbb P_{J,\,\sigma_0\sim\pi_{n,\beta}^J}
 \left\{T_{n,\beta}^J(\sigma_0)
       \le\exp\bigl(n^{1-c_\beta}\bigr)\right\}
 \longrightarrow1
 \qquad\text{as }n\longrightarrow\infty.
\]
The exponent is independent of $n$ and of the realized disorder.
The proof permits $c_\beta=1/40000000$ for every fixed $\beta>1$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every integer $r\ge3$ there is a finite constant $C_r$ such that,
for every integer $n\ge r$, every $0<p<1$, and every hypergraph property
$f:\{0,1\}^{E_{n,r}}\to\{0,1\}$,
\begin{equation}\label{eq:main}
 \Var_p(f)\le \frac{C_r}{(\log n)^{r/(r-1)}}I_p(f).
\end{equation}
No monotonicity assumption is required.
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a group $H$ of type $\Finfty$ such that every finitely
presented group admits an injective homomorphism into $H$.
\end{theorem}

\begin{theorem}[Unbounded configuration gap]\label{thm:unbounded-gap}
For every integer $c\ge0$, there is a finite rational bin-packing instance
$I$ and an integer $B$ such that every item size exceeds $1/6$ and
\begin{equation}\label{eq:main-gap}
  \LP(I)=B,
  \qquad \OPT(I)>B+c.
\end{equation}
The equality for the fractional optimum also holds for the configuration
LP whose patterns are subsets of the individual item copies.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a finite integer $N>3$, divisible by eight, and there are reduced
polynomials $f_1,f_2\in\R[z_1,\ldots,z_N]$, weighted homogeneous for
positive rational weights, such that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item each $f_j$ has an isolated critical point at the origin;
\item $\ord_0f_1=2$ and $\ord_0f_2=3$;
\item there is a homeomorphism germ of ambient pairs
\[
 (\C^N,V(f_1),0)\ \cong\ (\C^N,V(f_2),0).
\]
\end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:main}
There is an Artin matrix \(M\) on 116 generators, with every
off-diagonal label in \(\{2,3,\infty\}\), such that \(A_M\) admits no
geometric action.  One explicit matrix is given in
Definition~\ref{def:matrix}.
\end{theorem}

\begin{theorem}\label{thm:main}
There is an absolute constant $C<\infty$ such that, for every
real-valued $f\in W^{1,1}(\R^2)$, the function $Mf$ is locally
integrable, belongs to $W^{1,1}_{\mathrm{loc}}(\R^2)$, and satisfies
\begin{equation}\label{eq:main}
 \int_{\R^2}|\nabla Mf|\,\dd x
 \le C\int_{\R^2}|\nabla f|\,\dd x.
\end{equation}
In particular, its distributional derivatives are represented by
globally integrable functions.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist fixed matrices $A_1,\ldots,A_{23},B_1,\ldots,B_{307}
\in\Sym^{100}$ such that, for every $x=(X,Z,y)\in\mathcal V$,
\[
 x\in K\quad\Longleftrightarrow\quad
 \text{there exists }v\in\R^{307}\text{ with }
 \sum_{\nu=1}^{23}x_\nu A_\nu+
 \sum_{j=1}^{307}v_jB_j\succeq0.
\]
The equivalence holds on the entire closed cone, including points
with singular $X$.
\end{theorem}

\begin{theorem}\label{thm:main}
There exists an infinite finitely presented simple amenable group.
\end{theorem}

\begin{theorem}[An isolated lowest mass]
\label{intro:main}
For the field $\phi$ just specified, there exist $m_1,Z,\delta>0$ and a
positive measure $\rho_{\mathrm{rest}}$ such that
\begin{equation}
 \rho=Z\delta_{m_1^2}+\rho_{\mathrm{rest}},
 \qquad
 \supp\rho_{\mathrm{rest}}\subset[(m_1+\delta)^2,\infty).
 \label{intro:atom}
\end{equation}
In particular, $m_1$ is the smallest mass in the support of the spin-field
two-point function.
\end{theorem}

\begin{theorem}\label{thm:main}
For every finite \(S\subset\Z\) and all real bounded compactly
supported measurable functions \(F_0,F_1,F_2\) on \(\R_+^2\),
\begin{equation}\label{eq:main}
 \sum_{k\in S}\sum_{\mathbf I\in\cA_k}
       \abs{L_{\mathbf I}(F_0,F_1,F_2)}
 \le 40\prod_{v=0}^2\norm{F_v}_{L^3(\R_+^2)}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There is a finite constant $C$ such that
\[
 \norm{T(f_1,f_2,f_3)}_{L^1(\R)}
 \le C\prod_{j=1}^3\norm{f_j}_{L^3(\R)}
 \qquad(f_1,f_2,f_3\in\mathcal S(\R)).
\]
Consequently $T$ has a unique bounded trilinear extension from
$L^3(\R)\times L^3(\R)\times L^3(\R)$ to $L^1(\R)$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a single deterministic algorithm which, for every positive integer $n$ and every $x\in\C^n$, computes $F_nx$ exactly. In the model above, including scalar preparation, schedule construction, and index work, its running time is
\begin{equation}\label{eq:main-bound}
 O\!\left(n(\log n)^\theta(\log\log n)^{4-\theta}\right)
\end{equation}
as $n\to\infty$. It suffices to supply the specified root $\zeta_{D_*}$ for an explicitly computable integer $D_*<1024n^3$.
\end{theorem}

\begin{theorem}
\label{thm:main}
For every integer $h\ge2$, the language $\OWL_h$ is recognized by a
nondeterministic automaton with $h+3$ states using no left moves. Every
equivalent deterministic two-way automaton with $s$ states satisfies
\begin{equation}
\label{eq:main-bound}
 4(s+2)^2\ge 2^{\lfloor(h-2)/31\rfloor}.
\end{equation}
If an initially accepting configuration counts as acceptance, $s+2$ in
\eqref{eq:main-bound} may be replaced by $s+1$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is an infinite periodic group with an ordinary finite
presentation. More precisely, the construction below gives a unital
associative $\F_2$-algebra $R$ for which $\St_{12}(R)$ is infinite,
finitely presented, and periodic.
\end{theorem}

\begin{theorem}\label{thm:main}
There exists an infinite residually finite group with an ordinary finite
presentation in which every element has finite 2-power order.
\end{theorem}

\begin{theorem}
\label{thm:main}
For every integer \(n\ge3\), there is a constant \(a_n>0\), depending
only on \(n\), such that every closed connected oriented smooth
\(n\)-manifold \(M\) and every smooth Riemannian metric \(g\) on \(M\)
satisfy
\begin{equation}
  \int_M(\Scal_g^-)^{n/2}\,dV_g\ge a_n\|M\|.
  \label{eq:main}
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a unital normal trace-preserving $*$-isomorphism
\[
 \Phi:L(\F_2)\longrightarrow L(\F_3).
\]
\end{theorem}

\begin{theorem}[First moment over primary primes]\label{thm:main}
As $X\longrightarrow\infty$,
\begin{equation}\label{eq:main}
 \sum_{\substack{N\pi\le X\\\pi\equiv1\pmod3\ \mathrm{prime}}}G(\pi)
 =\frac65c_*\frac{X^{5/6}}{\log X}
   +o\!\left(\frac{X^{5/6}}{\log X}\right).
\end{equation}
The sum is over all primary primes in $\mathcal O$.
\end{theorem}

\begin{theorem}[Full annular variation]\label{thm:variation}
For every real $r>2$ there is a finite constant $C_r$ such that
\[
 \|V_r(F,G)\|_{L^{3/2}(\R^2)}
 \le C_r\|F\|_{L^3(\R^2)}\|G\|_{L^3(\R^2)}
\]
for all complex $F,G\in L^3(\R^2)$.
\end{theorem}

\begin{theorem}[Anticanonical nonvanishing]\label{thm:headline}
Let \(X\) be a smooth connected projective variety over \(\C\).
If \(-K_X\) admits a smooth Hermitian metric of semipositive curvature,
then \(H^0(X,-mK_X)\ne0\) for some integer \(m>0\).
\end{theorem}

\begin{theorem}\label{sal:main}
Let $\beta\in(1,2)$ be a Salem number of degree four.  Then the unbiased
Bernoulli convolution $\nu_{1/\beta}$ is singular with respect to Lebesgue
measure.
\end{theorem}

\begin{theorem}\label{np:main}
The polynomial \(p\) in \eqref{np:polynomial} has a unique real root
\(\beta\in(1.8392,1.8393)\). This root is not a Pisot number, and
\(\nu_{1/\beta}\) is singular with respect to Lebesgue measure.
\end{theorem}

\begin{theorem}[Height universality through the roughening threshold]
\label{main:heights}
For every admissible $J$, the threshold in
Equation~\eqref{main:physical-threshold} satisfies $0<\bc(J)<\infty$.
The supremum there is finite when $0<\beta<\bc(J)$ and infinite when
$\beta\ge\bc(J)$, including equality.

There are an integer $L=L(J)\ge2$ and a unique positive function
$\beff(J,\beta)$, defined for $\beta\ge\bc(J)$, such that along the
full sequence $N\to\infty$
\begin{equation}\label{main:height-limit}
 H_N\ \Longrightarrow\
       \sqrt{\frac{\beff(J,\beta)}{v_J^2}}\,\Phi_{\T}
       \quad\hbox{in }H^{-3}(\T^2).
\end{equation}
For every smooth real mean-zero $f$,
\begin{equation}\label{main:height-laplace}
 \lim_{N\to\infty}\log\E e^{H_N(f)}
 =\frac{\beff(J,\beta)}{2v_J^2}
           (f,(-\Delta_{\T})^{-1}f).
\end{equation}
Furthermore,
\begin{align}
 \beff(J,\bc(J))&=8\pi v_J^2,\label{main:height-endpoint}\\
 \lim_{\beta\downarrow\bc(J)}
 \frac{\beff(J,\beta)-\beff(J,\bc(J))}{\beta-\bc(J)}
    &=+\infty.\label{main:height-slope}
\end{align}
The function $\beff(J,\cdot)$ is differentiable on $(\bc(J),\infty)$,
and for some $c_J>0$,
\begin{equation}\label{main:height-high-temperature}
 \beff(J,\beta)=\beta+O_J(e^{-c_J\beta})\qquad(\beta\to\infty).
\end{equation}
For $J_\rho=\{x\in\Z^2\setminus\{0\}:|x|_\infty\le\rho\}$,
\begin{equation}\label{main:height-spread}
 \frac{\bc(J_\rho)}{8\pi v_{J_\rho}^2}\longrightarrow1
      \qquad(\rho\to\infty).
\end{equation}
In particular $v_{J_{\nn}}^2=1/4$ and the nearest-neighbor effective
temperature at roughening is $2\pi$.
\end{theorem}

\begin{theorem}[Full low-temperature spin-field limits]
\label{main:spins}
For each $M\in\{\mathrm{Villain},\mathrm{XY}\}$ there are a finite
$b_0(M)>0$ and functions $K_M(b)>1/(4\pi)$ and $A_M(b)>0$,
defined for all $b\ge b_0(M)$, with $K_M(b)/b\to1$ as $b\to\infty$,
such that
\begin{equation}\label{main:spin-limit}
 S_{M,b,n}:=n^{-2}\sum_{x\in D_n^\circ}
       A_M(b)e^{G_n(x,x)/(2K_M(b))}e^{i\theta_x}\delta_x
       \ \Longrightarrow\ V_{K_M(b),D}
\end{equation}
along the full sequence of integers $n\to\infty$, with tightness and
convergence in $H^{-3}_{\mathrm{loc}}(D)$.
For every finite collection of complex smooth compactly supported test
functions, their smeared fields converge jointly, including real and
imaginary parts.  The coefficients $K_M(b)$ and $A_M(b)$ are independent
of the test functions, the insertion locations, and $n$.
\end{theorem}

\begin{theorem}[Villain coefficient bridge]\label{main:bridge}
The choices in Theorem~\ref{main:spins} can be made so that
$\pi^2b\ge\bc(J_{\nn})$ throughout the asserted Villain range and
\begin{equation}\label{main:bridge-equality}
 K_{\mathrm{Villain}}(b)
       =\frac{\beff(J_{\nn},\pi^2b)}{\pi^2}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Let $X$ be a finite set and let $r\in F(X)$. If the one-relator group
$G=\langle X\mid r\rangle$ contains no subgroup isomorphic to
$\operatorname{BS}(m,n)$ for any nonzero integers $m,n$, then $G$ is
word-hyperbolic.
\end{theorem}

\begin{theorem}[Bloch's law]
\label{thm:main}
For every fixed $S\in\{\tfrac12,1,\tfrac32,\ldots\}$ and every
interaction satisfying \eqref{eq:interaction},
\begin{equation}
 \lim_{\beta\to\infty}\beta^{3/2}\bigl(S-m_{S,J}(\beta)\bigr)
   =\frac{\zeta(3/2)}{8\pi^{3/2}\sqrt{\det D_{S,J}}}.
 \label{eq:bloch-law}
\end{equation}
\end{theorem}

\begin{theorem}
\label{thm:bochner-riesz}
For every $\delta>0$, there is a finite constant $C_\delta$ such that
\begin{equation}
 \norm{T_\delta f}_{L^3(\RR^3)}
 \le C_\delta\norm f_{L^3(\RR^3)}
 \qquad(f\in\mathcal S(\RR^3)).
 \label{eq:main-bound}
\end{equation}
Consequently $T_\delta$ has a unique bounded extension to $L^3(\RR^3)$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every $a>0$, there is $\rho_*(a)>0$ such that for each fixed
$0<\rho<\rho_*(a)$ there is a fixed temperature $T=T(a,\rho)>0$ for which
\[
 \liminf_{\substack{L\to\infty\\N/L^3\to\rho}}
 \frac{\langle u_{0,L},\gamma^{(1)}_{N,L,T}u_{0,L}\rangle}{N}>0.
\]
The exclusion distance, density, and temperature are held fixed in this
limit.
\end{theorem}

\begin{theorem}\label{four:maximal:thm:main}
Let \((M,g,K)\) be a smooth connected orientable initial-data exterior,
diffeomorphic to \(\R^4\) minus an open ball, complete up to its connected
compact boundary \(S\cong S^3\), and with one asymptotically flat end.
Here \(K\) is a symmetric covariant two-tensor. Assume the vacuum constraint
equations with zero cosmological constant and maximality:
\begin{equation}\label{four:maximal:intro:constraints}
 R_g+(\tr_gK)^2-|K|_g^2=0,\qquad
 \divg_g\bigl(K-(\tr_gK)g\bigr)=0,\qquad \tr_gK=0.
\end{equation}
Assume a smooth effective \(T^2=U(1)\times U(1)\) action preserving \(g,K\)
which, in an asymptotically Euclidean chart \(\R^4=\mathbb C^2\), is
\[
 (e^{i\alpha},e^{i\beta})\cdot(z_1,z_2)
       =(e^{i\alpha}z_1,e^{i\beta}z_2)
\]
at all sufficiently large radii. No cohomogeneity-one assumption is made.
In that chart suppose
\begin{equation}\label{four:maximal:intro:decay}
 g_{ij}-\delta_{ij}=O_2(r^{-q}),\qquad
 K_{ij}=O_1(r^{-q-1}),\qquad q>1.
\end{equation}
Suppose the following ADM limits exist and are finite:
\begin{align}
 E&=\frac{1}{6\omega_3}\lim_{r\to\infty}
     \int_{|x|=r}(\partial_jg_{ij}-\partial_ig_{jj})
                  \nu_\delta^i\dd A_\delta,\label{four:maximal:intro:energy}\\
 P_i&=\frac{1}{3\omega_3}\lim_{r\to\infty}
     \int_{|x|=r}\bigl(K_{ij}-(\tr_gK)g_{ij}\bigr)
                  \nu_\delta^j\dd A_\delta.\label{four:maximal:intro:momentum}
\end{align}
Assume \(P=0\) and \(E>0\).

Orient \(S\) by its unit normal \(\nu\) toward the end and set
\(H_S=\divg_S\nu\). Suppose
\begin{equation}\label{four:maximal:intro:mots}
 \Theta_K(S):=H_S+\tr_SK=0.
\end{equation}
Suppose \(S\) is outermost toward the end: there is no compact smooth
embedded two-sided hypersurface in the interior enclosing \(S\), oriented
toward the end, with \(\Theta_K\le0\) everywhere. Suppose also that \(S\)
is outer area-minimizing: every compact smooth embedded enclosing
hypersurface has three-volume at least \(A=|S|_g\). Disconnected and
noninvariant enclosing competitors are included.
Then
\begin{equation}\label{four:maximal:intro:main-inequality}
 E\ge\frac12\left(\frac{A}{2\pi^2}\right)^{2/3}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
For every integer $d\ge3$, there exist constants $D<\infty$, $\eps>0$,
and finite connected pure $d$-dimensional simplicial complexes $X_m$,
with $|X_m(0)|\longrightarrow\infty$, such that every vertex belongs to
at most $D$ faces of dimension $d$ and, for every
$f\in C^i(X_m;\F)$,
\begin{equation}\label{eq:goal}
 \norm{\delta_i f}_{X_m,i+1}
 \ge \eps\,\dist_{X_m,i}(f,B^i(X_m))
 \qquad(0\le i<d).
\end{equation}
The constants are independent of $m$, $i$, and $f$.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $d\ge1$, let $\mathcal C\subset\mathbb Z_{\ge0}^d$ be finite, let $\mathcal R$ be
weakly reversible, and let all reaction rates be positive constants.
For every $x^0\in\R_{>0}^d$, the solution of \eqref{eq:mass-action} with
$x(0)=x^0$ exists for every $t\ge0$. There is a number
$\varepsilon\in(0,1)$, depending on the network, the rates, and $x^0$, such
that
\begin{equation}\label{eq:main-bounds}
 \varepsilon\le x_i(t)\le\varepsilon^{-1}
 \qquad(t\ge0,\ 1\le i\le d).
\end{equation}
\end{theorem}

\begin{theorem}[Finite-graph comparison]\label{in:comparison}
For every two configurations $b,b'$ on $J$ and every configuration $a$
on $I$,
\[
 e^{-4\operatorname{arctanh}q_0}
 \leq
 \frac{\mu(\sigma_I=a\mid\sigma_J=b,\sigma_F)}
      {\mu(\sigma_I=a\mid\sigma_J=b',\sigma_F)}
 \leq e^{4\operatorname{arctanh}q_0}.
\]
Either conditional law may be replaced by an arbitrary mixture of
these laws. The bound is symmetric in the two terminal sets.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $X$ be a compact connected K\"ahler manifold of positive complex
dimension. If every holomorphic map $\C\to X$ is constant, then $K_X$ is
ample. In particular, a positive tensor power of $K_X$ defines a
holomorphic embedding of $X$ into a complex projective space.
\end{theorem}

\begin{theorem}[Joint canonical limit]\label{intro:main}
There is a deterministic sequence
$a_n=a_n(q)>0$ with $a_n\to0$ such that, through all positive integers,
\begin{equation}\label{intro:joint-convergence}
 \big((\phi_n)_*m_n,K_n(a_n),\Gamma_n\big)
 \ \Longrightarrow\
 \big(\mu_h,\{(z,w,D_h(z,w)):z,w\in\Chat\},\Gamma\big).
\end{equation}
The three topologies are weak convergence of probability measures,
Hausdorff convergence of the full distance graphs, and uniform
reparameterization matching of loop collections as defined in
\cref{intro:loop-topology}. Moreover,
\begin{equation}\label{intro:mesh-conclusion}
 \max_{T\text{ a flag triangle of }X_n}
       \diam_{\rho}\phi_n(T)\ \longrightarrow\ 0
 \qquad\text{in probability},
\end{equation}
where $\rho$ is spherical distance. The conditional law of $\Gamma$ is
independent of the embedded marked quantum surface.
\end{theorem}

\begin{theorem}[Annealed Voronoi crossing law]\label{thm:cardy}
For every bounded Jordan domain $D$ and every four distinct
counterclockwise boundary marks $a,b,c,d$, one has
\begin{equation}\label{eq:cardy}
 \lim_{\eps\downarrow0}\PP\bigl(\mathcal C_\eps(D;a,b,c,d)\bigr)
 =F(x)
 :=\frac{\displaystyle\int_0^x[u(1-u)]^{-2/3}\,\dd u}
          {\displaystyle\int_0^1[u(1-u)]^{-2/3}\,\dd u}
 =\frac{\Gamma(2/3)x^{1/3}}
        {\Gamma(1/3)\Gamma(4/3)}
        {}_2F_1\!\left(\frac13,\frac23;\frac43;x\right).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Catalan's constant is irrational.
\end{theorem}

\begin{theorem}\label{thm:main}
The query $Q$ on all finite structures in the fixed vocabulary $\tau$ of
eight binary relations is isomorphism-invariant and decidable in
deterministic polynomial time, but is not definable in full choiceless
polynomial time with counting.
\end{theorem}

\begin{theorem}\label{thm:main}
For all $\gamma,\nu\in[0,1]$ and every integer $n\ge1$,
\begin{equation}\label{eq:main}
 \chi(\A_{\gamma,\nu}^{\otimes n})
 =n\chi(\A_{\gamma,\nu})
 =\frac n{\ln2}\max_{0\le p\le1}
 \{h((1-\gamma)p+\gamma\nu)-g(v_{\gamma,\nu}(p))\},
\end{equation}
where
\begin{equation}\label{eq:v-main}
 v_{\gamma,\nu}(p)
 =\gamma\nu(1-\nu)+\gamma(1-\gamma)(p-\nu)^2.
\end{equation}
In particular, $C(\A_{\gamma,\nu})=\chi(\A_{\gamma,\nu})$.
If $p$ maximizes \eqref{eq:main}, independent products of the two
equiprobable signals
\begin{equation}\label{eq:pair}
 \phi_\pm=\sqrt{1-p}\,\ket0\ \pm\sqrt p\,\ket1
\end{equation}
attain the Holevo information at every block length.
\end{theorem}

\begin{theorem}\label{tra:regular-ranks:main}
There is an absolute $c>0$ such that
\begin{equation}
                             s_j(T_N)\le j^{-c}\qquad (1\le j\le N!)\label{tra:regular-ranks:eq1}
\end{equation}
for every power of two $N$.
\end{theorem}

\begin{theorem}[Weighted compatibility]\label{tra:duality:weighted}\label{tra:duality:weighted-statement}
There are absolute constants $L,C_0>0$ such that the following holds. Put $m=\sqrt n$, assume $m/2\le A,D\le2m$, and take $m$ sufficiently large that $\theta=1-L/\log m>0$. For all nonnegative functions $w_i:S_D\to[0,\infty)$ and $v_k:S_A\to[0,\infty)$,
\begin{equation}\label{tra:duality:eq5}
 \frac{n!}{|R||C|}\,
 \mathbb E_U\!\left[\mathbf1_{\mathcal I}
       \prod_{i=1}^A w_i(r_i)\prod_{k=1}^D v_k(c_k)\right]
 \le e^{C_0n^{.54}}
       \prod_{i=1}^A(\mathbb E w_i^{1/\theta})^\theta
       \prod_{k=1}^D(\mathbb E v_k^{1/\theta})^\theta .
\end{equation}
The expectations on the right are uniform on the indicated symmetric groups, and logarithms are natural.
\end{theorem}

\begin{theorem}[Compact support and rapid decay]
\label{thm:rapid}
Fix a positive computable viscosity $\nu$. From a deterministic Turing machine $M$ and a
finite input $w$ one can effectively construct a smooth force on
$[0,\infty)\times\R^3$, supported for all times in the fixed compact set
\[
 K=[-2,1]\times[-1,2]\times[-1,1],
\]
such that, for every pair of nonnegative integers $J,l$ and spatial
multi-index $\alpha$,
\begin{equation}
 \sup_{t\geq0,\,x\in\R^3}
 (1+t)^J\bigl|\partial_t^l\partial_x^\alpha f(t,x)\bigr|<\infty.
 \label{eq:rapid-force-bound}
\end{equation}
The Navier--Stokes equation with this force and zero initial velocity has
an explicit global smooth solution, unique in the finite-interval class \eqref{eq:energy-class}.  Its material trajectory from
the origin satisfies
\begin{equation}
 M\text{ halts on }w
 \quad\Longleftrightarrow\quad
 X_1(t,0)<-1\text{ for some }t\geq0.
 \label{eq:rapid-event}
\end{equation}
The velocity has the same fixed support and rapid mixed-derivative bounds.
The pressure is zero. The force is a general body force. Because $K$ is fixed,
the same bounds hold with $(1+t+|x|)^J$ in place of $(1+t)^J$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a real number $\alpha_3\in(0,\infty)$ such that, for every fixed
real $a\ge0$,
\[
 \lim_{n\to\infty}p(n,\lfloor an\rfloor)=
 \begin{cases}1,&a<\alpha_3,\\0,&a>\alpha_3.\end{cases}
\]
There is one finite deterministic Turing machine which, on input $1^r$
for any integer $r\ge1$, halts with a rational number $q_r$ satisfying
$|q_r-\alpha_3|\le2^{-r}$. Its only input is the unary precision $1^r$;
it uses no oracle, advice, or noncomputable real constant.
\end{theorem}

\begin{theorem}[Replica entropy route]\label{c:rep:main}
For the physical Thorp shuffle on $N=2^d$ cards,
\[
 \|q_d^{*(1327104d)}-U_{S_N}\|_{\TV}\longrightarrow0.
\]
More precisely, put $L=256$, $q=N-N/L$, and let $w$ be the law after $16384d$ physical
shuffles. Averaging over all ordered distinct $q$-tuples $I$, its projected law satisfies
\begin{equation}
 \E_I\KL(w_I\|\mathbf u_q)=O(d^4).\label{c:rep:e1}
\end{equation}
Here $\mathbf u_q$ is uniform on ordered distinct $q$-tuples, and
$\KL(p\|u)=\sum_xp(x)\log(p(x)/u(x))$, with zero summands interpreted as zero.
\end{theorem}

\begin{theorem}[Riemannian Penrose inequality with minimizing frontiers]
\label{thm:rpi}
Let $(E,h)$ be a connected complete $n$-dimensional exterior, including
its compact frontier $\Sigma$ in the enclosing-set sense above. Suppose
that $h$ is smooth on $E$ and through $\Sigma$, and that
\begin{enumerate}
\item $R_h\ge0$, $R_h\in L^1(E,dV_h)$, and
      $R_h=O(r^{-n-\beta})$ for some $\beta>0$ on the end;
\item outside a compact set there is exactly one Euclidean coordinate
      end with $h-\delta=O_2(r^{-\tau})$, where $\tau>d/2$;
\item the full frontier is outer minimizing and locally perimeter
      minimizing as the boundary of the filled side. Its regular part
      is a smooth embedded minimal hypersurface, and its singular set
      has Hausdorff dimension at most $n-8$.
\end{enumerate}
Then
\begin{equation}\label{eq:rpi:numerical}
 m_{\rm ADM}(h)\ge\frac12
 \left(\frac{\mathcal H_h^k(\Sigma)}{\omega}\right)^{d/k}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
The promise problem above is QMA-hard under deterministic classical polynomial-time many-one reductions for $c=1$. The reduction can produce instances with $b-a\ge1$.
\end{theorem}

\begin{theorem}\label{thm:main}
Using the height, renormalization, and spin-field inputs from
\cite{B,X,S} stated in Section~\ref{sec:inputs}, there is a constant
\(A_{\mathrm{XY}}\in(0,\infty)\) such that
\begin{equation}\label{eq:main}
 a_n=A_{\mathrm{XY}}\,n^{-1/8}(\log n)^{1/16}(1+o(1))
                       \qquad(n\to\infty).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
For nearest-neighbor Bernoulli bond percolation on $\mathbb Z^3$, there is
almost surely no infinite open cluster at the bond critical parameter.
The same assertion holds for nearest-neighbor Bernoulli site percolation
at the site critical parameter.
\end{theorem}

\begin{theorem}[Critical local smoothing]\label{thm:main}
For every $\eps>0$ there exists $C_\eps<\infty$ such that
\begin{equation}\label{eq:intro-main}
 \norm{Uf}_{L^3(\R^3\times[1,2])}
 \le C_\eps\norm{J^\eps f}_{L^3(\R^3)}
 \qquad (f\in\mathcal S(\R^3)).
\end{equation}
\end{theorem}

\begin{theorem}[Critical mixing and functional inequalities]
\label{thm:main}
For every fixed $\varepsilon\in(0,1/2)$, in probability over the Gaussian
disorder,
\begin{align*}
 t_{\mathrm{mix},J}(\varepsilon)&=n^{2/3+o(1)},&
 k_{\mathrm{mix},J}(\varepsilon)&=n^{5/3+o(1)},\\
 R_J&=n^{2/3+o(1)},& C_{\mathrm{LS},J}&=n^{2/3+o(1)}.
\end{align*}
In each expression, $X_n=n^{a+o(1)}$ means that for every fixed
$\delta>0$, $\Pprob\{n^{a-\delta}\le X_n\le n^{a+\delta}\}\to1$.
\end{theorem}

\begin{theorem}[Realized equilibrium initial states]\label{thm:gibbs-start}
For every deterministic sequence $t_n\ge0$ with $t_n=o(n^{2/3})$,
\[
 \mu_W\{x:d_{t_n}^{\rm ct}(W,x)>1/4\}
 \xrightarrow{\Prob}1.
\]
For every deterministic integer sequence $k_n\ge0$ with $k_n=o(n^{5/3})$,
\[
 \mu_W\{x:d_{k_n}^{\rm dt}(W,x)>1/4\}
 \xrightarrow{\Prob}1.
\]
The convergence is in probability over the disorder.
\end{theorem}

\begin{theorem}[Critical strip mass]\label{thm:strip}
For every integer $N\ge1$, all sums in
\eqref{eq:01-strip-quantities} are finite. With constants independent of
$N$,
\begin{equation}\label{eq:01-strip-result}
 c\mathcal A_N+\mathcal B_N=1,\qquad
 m_{N+1}-m_N\asymp\mathcal B_N,\qquad
 m_N\asymp N^{3/4},\qquad
 \mathcal B_N\asymp N^{-1/4}.
\end{equation}
Moreover, $\mathcal B_N$ is nonincreasing in $N$.
\end{theorem}

\begin{theorem}[Simple comparison and absorption]
\label{ext:thm:main}
Let $A$ be a separable simple nuclear non-elementary $C^*$-algebra.
If $A$ has strict comparison in the sense of
Equation~\eqref{ext:eq:comparison}, then $A\cong A\otimes_{\min}\Z$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every prime \(p\), finite \(p\)-group \(G\), subgroup \(H\le G\), and integer \(n\ge0\),
\[
 \boxed{r_n(G,H)=\ell(G,H).}
\]
\end{theorem}

\begin{theorem}[Cylinder fugacity exponent]
\label{thm:04-cylinder-exponent}\label{E:cylinder-exponent}
For every fixed $\chi>0$, along even $N$,
\[
 Z_N(\chi)=N^{\tau(\chi)+o(1)},\qquad
 \tau(\chi)=
 \begin{cases}
 \displaystyle\frac16-\frac{2}{3\pi^2}
              \bigl(\arccos(\chi/2)\bigr)^2,&0<\chi\le2,\\[4pt]
 \displaystyle\frac16+\frac{2}{3\pi^2}
              \bigl(\operatorname{arcosh}(\chi/2)\bigr)^2,&\chi\ge2.
 \end{cases}
\]
\end{theorem}

\begin{theorem}\label{thm:main}
Let $X$ be a closed connected oriented smooth four-manifold, and let
$\omega=(\omega_1,\omega_2,\omega_3)$ be a smooth hypersymplectic structure
normalized by
\begin{equation}\label{eq:intro-normalization}
 \int_X\omega_i\wedge\omega_j=\delta_{ij}.
\end{equation}
There is a smooth family of hypersymplectic structures $\omega(t)$,
$0\le t\le1$, such that
\[
 \omega(0)=\omega,\qquad [\omega_i(t)]=[\omega_i]
 \quad (i=1,2,3),
\]
and a positive volume form $\mu_1$ with
\begin{equation}\label{eq:intro-endpoint}
 \omega_i(1)\wedge\omega_j(1)=2\delta_{ij}\mu_1.
\end{equation}
The endpoint forms are parallel and self-dual for a hyperk\"ahler metric.
\end{theorem}

