\begin{theorem}\label{thm:main}
Let \(\Sigma\subset\R^3\) be a compact smooth positively curved
surface, possibly with smooth boundary. For every \(3<p<\infty\),
there is a finite constant \(C_{\Sigma,p}\) such that
\begin{equation}\label{eq:main}
 \|E_\Sigma f\|_{L^p(\R^3)}
 \le C_{\Sigma,p}\|f\|_{L^p(\Sigma)}
\end{equation}
for every complex-valued \(f\in L^p(\Sigma)\).
\end{theorem}

\begin{theorem}\label{thm:main}
There are absolute constants $c,C>0$ and an integer $d_0$ such that, for
every integer $d\ge d_0$ and every finite alphabet $\Sigma$ with
$|\Sigma|\ge2$,
\begin{equation}\label{eq:main}
 \exp\!\bigl(c\sqrt{\log d\,\log\log d}\bigr)
 \le E_\Sigma(d)\le
 \exp\!\bigl(C\sqrt{\log d\,\log\log d}\bigr).
\end{equation}
The lower bound is witnessed by a subset of binary strings of one common
length at most $d$. The same bounds hold for
$\sup_{\Sigma:\,2\le|\Sigma|<\infty}E_\Sigma(d)$.
\end{theorem}

\begin{theorem}[Elementary positivity and a permutation witness]
\label{main:theorem}
There is a deterministic terminating procedure which, given a natural
unit interval graph $G$ on $[n]$ and $\sigma\in D_G^0$, returns a partition
$\theta_G(\sigma)\vdash n$ such that
\begin{equation}
 \chi_G(X;q)=\sum_{\sigma\in D_G^0}
       q^{\ginv_G(\sigma)}e_{\theta_G(\sigma)}(X).
 \label{main:witness}
\end{equation}
In particular every elementary coefficient of $\chi_G(X;q)$ belongs to
$\N[q]$. The assertion holds as a formal symmetric-function identity,
uniformly in $n$ and $G$.
\end{theorem}

\begin{theorem}[The elliptic-square case]\label{intro:squares}
Let $C\subset\A_2$ be a nonempty reduced irreducible closed algebraic
curve over $\Qbar$. If $C$ is Hodge generic, then $\Sigma_{E^2}(C)$ is
finite.
\end{theorem}

\begin{theorem}\label{thm:main}
For every real \(p>3\), there is a finite constant \(C_p\), depending
only on \(p\), such that
\[
  \|Eg\|_{L^p(\R^3)}
  \le C_p\|g\|_{L^\infty(S^2,\sigma)}
\]
for every bounded measurable complex-valued function \(g\) on \(S^2\).
\end{theorem}

\begin{theorem}[Geometric propagation]\label{geo:main}
For \(0<s\le1\) and \(0<\kappa<1/10\),
\begin{equation}\label{eq:source-4}
q_*\ge1+2s-10\kappa.
\end{equation}
\end{theorem}

\begin{theorem}[Uniform propagation of finite packet arrays]\label{pkt:main}
Fix \(0<\kappa<1/10\), the continued phase, a bounded frequency region,
and the window system above.  For every fixed admissible complexity
range and every \(\varepsilon>0\), there is a finite constant \(C\) such
that
\begin{equation}\label{pkt:uniform-main}
 \mathcal A(T_m d)^3
   \le C m^{10\kappa+\varepsilon}G(d)^3
\end{equation}
for every finite complex initial array \(d\) and every terminal
coordinate mask in that range.  The same estimate holds with \(A(d)^3\)
on the right.  The constant is uniform in \(m,N,d\), and the masks; it
may depend on \(\kappa,\varepsilon\), the complexity range, the fixed
phase and frequency region, and the windows.  Equivalently,
\begin{equation}\label{eq:source-32}
 \gamma\le10\kappa.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main-state}
There is an explicitly specified entangled density operator $\rho$ on
$\C^{10}\otimes\C^{10}$ whose range contains no nonzero product vector and
for which $K_D(\rho)=0$.  More precisely, let $n\geq1$ and let
$\tau_{K_AK_BE'}$ be the normalized output of any admitted completed bit-output protocol of
Definition~\ref{def:protocol} on $\rho^{\otimes n}$, where $E'$ retains an
initial purification and the complete public transcript.  For every state
$\sigma_{E'}$,
\begin{equation}\label{eq:main-gap}
 \left\lVert \tau_{K_AK_BE'}-
 \frac12\sum_{i=0}^1|i,i\rangle\langle i,i|\otimes\sigma_{E'}
 \right\rVert_1\geq\frac15.
\end{equation}
Thus the corresponding trace distance, with its conventional factor
$1/2$, is at least $1/10$.
\end{theorem}

\begin{theorem}\label{thm:main-channel}
There is an explicitly specified trace-preserving PPT channel
$\Theta:\Mat{21}\to\Mat{21}$ whose square $\Theta\circ\Theta$ is not
entanglement breaking.
\end{theorem}

\begin{theorem}[Pointwise entropy bounds]\label{ent:main}
Let $G$ be a loopless multigraph on $2m\ge2$ vertices with at least one
perfect matching. For every $x\in P(G)$,
\begin{equation}\label{intro:main-bound}
                  F(x)-\left(2-\frac2m\right)B(x)
                  \le H(x)\le F(x).
\end{equation}
\end{theorem}

\begin{theorem}[Numerical input]\label{thm:numerical-input}
The numerical spacetime Penrose theorem \cite[Theorem~1.3]{CompanionNumerical} states that every initial-data exterior in Definition~\ref{def:data}, with
the positive full-cut infimum in Definition~\ref{def:fullcuts}, satisfies
\begin{equation}
 \boxed{\quad
 m\ge\frac12
 \left(\frac{A_{\min}(S)}{\omega}\right)^{\frac{n-2}{n-1}} .
 \quad}
 \label{eq:setting:main}
\end{equation}
This input is used for nearby weakly trapped data as well as for the
original pair. It imposes none of the additional equality hypotheses
introduced below.
\end{theorem}

\begin{theorem}[Equality classification]\label{thm:main}
For every $W$ satisfying~\eqref{intro:class},
\begin{equation}\label{intro:sharp}
 \Tr(H_W)_-^\gamma\le C_\gamma\int_\R\tr(W^p),
 \qquad
 C_\gamma=\left(\frac{\gamma-1/2}{\gamma+1/2}\right)^{\gamma-1/2}
       \frac{\Gamma(\gamma+1)}{\sqrt\pi\,\Gamma(\gamma+3/2)}.
\end{equation}
Put $r=(\gamma-1/2)^{-1}$. Equality holds if and only if there are
$k\in\{0,\ldots,m\}$, a constant unitary matrix $U$, positive numbers
$a_1,\ldots,a_k$, and real numbers $x_1,\ldots,x_k$ such that almost
everywhere
\begin{equation}\label{intro:classification}
 W(x)=U\diag\bigl(w_1(x),\ldots,w_k(x),0,\ldots,0\bigr)U^*,
 \quad
 w_j(x)=(r+1)a_j^2\sech^2\!\bigl(ra_j(x-x_j)\bigr).
\end{equation}
The case $k=0$ means $W=0$. Each nonzero channel has exactly one negative
eigenvalue, $-a_j^2$, and therefore every extremal potential has at most
$m$ negative eigenvalues, counted with multiplicity.
\end{theorem}

\begin{theorem}\label{thm:main}
For the model \eqref{eq:spin-law}, there is a constant $A_{\mathrm{XY}}\in(0,\infty)$ such that
\begin{equation}\label{eq:main-limit}
 \lim_{b\uparrow b_c}\sqrt{b_c-b}\,\log\xi(b)=A_{\mathrm{XY}}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:exterior}
For the fixed disks and exterior above, there is a smooth proper
connected curve $Y/\bar k$ and a finite \'etale surjective morphism
$g:Y\to X$ such that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item a connected component of $g^{-1}(U)$ maps isomorphically to $U$;
\item for every $i$, every connected component of $g^{-1}(V_i)$
maps to $V_i$ with degree divisible by $p$.
\end{enumerate}
Here the inverse images and the degrees of their components refer
to the induced finite \'etale analytic maps. The disks are the prescribed
$V_i$; they are not shrunk in the conclusion.
\end{theorem}

\begin{theorem}[The qualitative form]\label{main:qualitative}
An AEC categorical in unboundedly many cardinals is categorical on a tail of
the cardinals.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $E/\Q$ be an elliptic curve and let $q$ be any prime. If
$s_q(E)\in\{0,1\}$, then
\[
 r(E)=a(E)=s_q(E),\qquad \#\Sha(E/\Q)<\infty,
\]
and, with $r=r(E)$ and the preceding normalizations,
\begin{equation}\label{eq:bsd-main}
 \frac{L^{(r)}(E,1)}{r!}
 =\frac{\Omega_E\Reg_E\,\#\Sha(E/\Q)
                  \prod_{\ell\text{ finite}}c_\ell(E)}
              {\#E(\Q)_{\rm tors}^{2}}.
\end{equation}
There are no additional hypotheses on reduction, rational torsion,
isogenies, complex multiplication, or residual Galois representations.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $E/\Q$ be an elliptic curve and let $q$ be any prime. If
$s_q(E)\in\{0,1\}$, then
\[
 r(E)=a(E)=s_q(E),\qquad \#\Sha(E/\Q)<\infty,
\]
and, with $r=r(E)$ and the preceding normalizations,
\begin{equation}\label{eq:bsd-main}
 \frac{L^{(r)}(E,1)}{r!}
 =\frac{\Omega_E\Reg_E\,\#\Sha(E/\Q)
                  \prod_{\ell\text{ finite}}c_\ell(E)}
              {\#E(\Q)_{\rm tors}^{2}}.
\end{equation}
There are no additional hypotheses on reduction, rational torsion,
isogenies, complex multiplication, or residual Galois representations.
\end{theorem}

\begin{theorem}[Exact logarithmic-space derandomization]\label{thm:main}
\[
                 \Lclass=\RL=\BPL.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For the measures \eqref{eq:gibbs}, the full transfer gap
\eqref{eq:mass-definition} satisfies
\begin{equation}\label{eq:main-limit}
 \lim_{\beta\to\infty}
    \frac{\exp(\pi\beta)}{\sqrt\beta}\,m_{\mathrm{lat}}(\beta)
       =32\exp\!\left(\frac\pi4-\frac12\right).
\end{equation}
\end{theorem}

\begin{theorem}\label{V:invariant-main}
Let $X$ be smooth connected projective over $\C$, with $-K_X$ smoothly
semipositive and $H^i(X,\OO_X)=0$ for every $i>0$. For every algebraic
torus $T$ acting on $X$, some positive anticanonical multiple has a
nonzero $T$-invariant section for its natural linearization.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a polynomial-time uniform family of polynomial-size quantum circuits that outputs the complete prime factorization of every input integer $N\ge2$ with probability one. The number of gates and qubits is bounded by a fixed polynomial in the bit length of $N$. One fixed finite gate set suffices: NOT, CNOT, Toffoli, Hadamard, $\operatorname{diag}(1,i)$, their inverses, and their singly controlled versions.
\end{theorem}

\begin{theorem}\label{thm:main}
There is a constant $c>0$ such that, for every fixed $0<\rho<1$,
there is $n_0=n_0(\rho)$ for which
\[
 \rankpsd A_n(\rho)\ge2^{cn}
\]
for every even $n\ge n_0$.
\end{theorem}

\begin{theorem}
\label{thm:main}
For every integer $n\ge3$ and every finite $\beta>0$, there are constants
$A=A(n,\beta)<\infty$ and $m=m(n,\beta)>0$ such that, for every finite
nearest-neighbor square-lattice subgraph $G$, every strength array
$b\in[0,\beta]^E$, and all $x,y\in V$,
\begin{equation}
 0\le \langle\sigma_x\cdot\sigma_y\rangle_{G,b}^{(n)}
 \le A\exp(-m\|x-y\|_2).
 \label{eq:main-bound}
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There is a countable, unbounded, nonproper pointed metric space $(M,d,o)$
such that $d(x,y)\ge1$ for distinct points and $\F(M)$ has AP but fails
$\lambda$-BAP for every finite $\lambda\ge1$.
\end{theorem}

\begin{theorem}\label{thm:main}
At \(p=n=3\), with \(S=S_3^\wedge\),
\[
             L_2L_{K(3)}S
                  \notin\Thick\{L_0S,L_1S,L_2S\}
\]
in the category of \(E(2)\)-local \(S\)-modules.
\end{theorem}

\begin{theorem}\label{thm:main}
Let \(n\geq1\) and let \(p>n+1\) be prime. There exist an
enumeration \(I_1,\ldots,I_{2^n}\) of the subsets of
\(\{1,\ldots,n\}\), a filtration \(F_\bullet\), and a family of
classes \(y_i\in\pi_{1-2i}D\), \(1\leq i\leq n\), with the
following properties.
\begin{enumerate}[label=(\alph*)]
\item \textbf{Filtration and unit.}
The enumeration has \(I_1=\varnothing\) and \(\max I_j\)
nondecreasing for \(j\geq2\). The filtration is
\[
 0=F_0\longrightarrow F_1\longrightarrow\cdots
 \longrightarrow F_{2^n}\xrightarrow{\simeq}X_{n,p}
\]
with \(\operatorname{cofib}(F_{j-1}\to F_j)\simeq C_{I_j}\), where
\begin{equation}\label{eq:pieces}
 \begin{aligned}
 C_\varnothing&=L_{n-1}S,\\
 C_I&=\Sigma^{-d(I)}L_{n-\max I}S
       \quad(I\ne\varnothing).
 \end{aligned}
\end{equation}
Under \(F_1=C_\varnothing\), the composite \(F_1\to X_{n,p}\) is the
canonical localization unit.
\item \textbf{Simultaneous product bases.}
For this one family, set \(y_\varnothing=1\) and
\(y_I=y_{i_1}\cdots y_{i_r}\) for \(I=\{i_1<\cdots<i_r\}\).
For every \(1\leq t<n\), the specified map
\begin{equation}\label{eq:height-basis}
 L_{K(t)}
 \left(\bigvee_{I\subseteq\{1,\ldots,n-t\}}
       \Sigma^{-d(I)}S\xrightarrow{(y_I)}D\right)
 \quad\text{is an equivalence}.
\end{equation}
\end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:main}
For every finitely generated group \(G\), the following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \(G\) has decidable word problem.
\item \(G\) embeds in a finitely presented simple group.
\end{enumerate}
\end{theorem}

\begin{theorem}\label{thm:counterexample}
The tetrahedron \eqref{eq:tetrahedron} has $A_{\min}(K)=\sqrt2$.
For every $0<\eps\le1/2000$, it admits a covering by
$m=2\lceil2/\eps^2\rceil$ cylinders with compact triangular perpendicular
bases such that
\begin{equation}\label{eq:main-asymptotic}
 \frac1{\sqrt2}\sum_{i=1}^m|B_i|
 =\frac12-\frac{13}{6000}\eps^2+O(\eps^4).
\end{equation}
The remainder has absolute value at most $2\eps^4$, and the total base
area is strictly less than $A_{\min}(K)/2$.
\end{theorem}

\begin{theorem}[Finite approximation by square tiles]\label{b:approximation}
Let $D\subset\R^2$ be compact, let $V$ be $C^1$ on an open
neighborhood of $D$, and let $L,h>0$. Suppose that
\begin{equation}\label{b:main-condition}
 \tr DV(p)=0,\qquad -L^{-2}<\det DV(p)\le0
 \quad(p\in D).
\end{equation}
For every $\varepsilon>0$, there are finitely many compact
nondegenerate square tiles $T_i\subset\R^2$, with possibly different
orientations, and velocities $g_i\in\R^2$ such that
\begin{equation}\label{b:main-cover}
 E(D,V,L)\subset\bigcup_i\Cyl(T_i,g_i),\qquad
 \sum_i |T_i|J_h(g_i)
 \le\int_D J_h(V(p))\,dp+\varepsilon.
\end{equation}
Under $F_h$, the perpendicular bases are compact nondegenerate
parallelograms and have total area $h\sum_i|T_i|J_h(g_i)$.
No condition on the area of $\partial D$ or smallness of $\|DV\|$
is required.
\end{theorem}

\begin{theorem}\label{thm:nonvanishing}
Let $X$ be a smooth connected projective complex fourfold. If $K_X$ is
pseudo-effective, then $H^0(X,mK_X)\ne0$ for some positive integer $m$.
\end{theorem}

\begin{theorem}[Quenched near-critical universality]
\label{thm:main}
Assume Hypothesis~\ref{hyp:cardy}. The expectations in
\eqref{eq:requested-scales} are finite and strictly positive for every
mesh, and both scales tend to zero as their mesh tends to zero.
There is a probability measure $\nu_\triangle$ on $\mathcal K$ such that
\begin{equation}
 \Law(\tau_\delta^\triangle)\Longrightarrow\nu_\triangle
 \qquad(\delta\downarrow0).
 \label{eq:triangular-reference}
\end{equation}
For the independently normalized Voronoi model,
\begin{equation}
 d_{\mathrm{BL}}\bigl(\Law(\tau_\varepsilon^V\mid\eta_\varepsilon),
                 \nu_\triangle\bigr)
 \xrightarrow[\varepsilon\downarrow0]{\PP}0.
 \label{eq:main-quenched}
\end{equation}
The conditional law averages all color marks and no geometry.
\end{theorem}

\begin{theorem}[Complementary cosets control Fourier matrices]
\label{l:main}
Partition $X$ into $b$ nonempty sets $M_1,\ldots,M_b$. Put $H_i=H_{M_i}$. Suppose $f$ is a nonnegative measure on $G$ of mass at most one and, for every $g\in G$ and $i$,
\begin{equation}\label{l:main-cap}
 f(gH_i)\le \frac{B}{[G:H_i]}.
\end{equation}
For every $u>0$ and every irreducible $\rho$ of degree $D$,
\begin{equation}\label{l:main-hs}
 \|\widehat f(\rho)\|_{\HS}^2
 \le bBC_uD^{-1+(u+2)/b}.
\end{equation}
There is also an independent orbit-span proof of the bound
\begin{equation}\label{l:main-orbit}
 \|\widehat f(\rho)\|_{\op}^2
 \le bBC_uD^{-1+(u+2)/b}.
\end{equation}
No restriction is imposed on block sizes or on the multiplicities in $\rho|_{H_1\times\cdots\times H_b}$.
\end{theorem}

\begin{theorem}[Full support at zero temperature]\label{thm:full-support}
If $\gamma\in\mathcal U$ minimizes $\mathcal P$, then
\[
 \supp\mu_\gamma=[0,1).
\]
In particular $\gamma(b)>\gamma(a)$ whenever $0\leq a<b<1$.
For the solution of~\eqref{eq:model-diffusion},
\begin{equation}\label{eq:main-consistency}
 \E[u_\gamma(t,X_t)^2]=t,\qquad
 \E[\Phi_{\gamma,xx}(t,X_t)^2]=1,
 \qquad 0\leq t<1.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
For every finite alphabet $\Sigma$ and every regular language
$L\subseteq\Sigma^*$, one has $h_\Sigma(L)\le4$.
\end{theorem}

\begin{theorem}[Generalized ionization energy]\label{thm:main}
For full nonrelativistic Coulomb atoms with two electron spin states,
\begin{equation}\label{eq:joint-limit}
 \frac{I_m(Z)}{m^{7/3}}\longrightarrow a_{\TF}>0
 \quad\text{whenever}\quad m\longrightarrow\infty,
 \qquad \frac Zm\longrightarrow\infty,
\end{equation}
where $Z>m\ge1$ are integers. In particular,
\begin{align}
 \lim_{m\to\infty}
  \frac{\limsup_{Z\to\infty} I_m(Z)}{m^{7/3}}
   &=a_{\TF},\label{eq:iterated-upper}\\
 \lim_{m\to\infty}
  \frac{\liminf_{Z\to\infty} I_m(Z)}{m^{7/3}}
   &=a_{\TF}.\label{eq:iterated-lower}
\end{align}
The inner limits are taken over integer $Z$ with $m$ fixed. No convergence
of $I_m(Z)$ at a fixed $m$ is asserted or assumed.
\end{theorem}

\begin{theorem}[Generalized ionization conjecture: radii]\label{intro:main}
Set $b_{\mathrm{TF}}=(81\pi^2/2)^{1/3}$.  For every choice of normalized
neutral ground states $(\Psi_Z)_{Z\ge1}$ of \eqref{intro:hamiltonian},
\begin{align}
 \lim_{m\to\infty}m^{1/3}
       \left[\limsup_{\substack{Z\to\infty\\ Z>m}}R_m(\Psi_Z)\right]
       &=b_{\mathrm{TF}},\label{intro:limsup}\\
 \lim_{m\to\infty}m^{1/3}
       \left[\liminf_{\substack{Z\to\infty\\ Z>m}}R_m(\Psi_Z)\right]
       &=b_{\mathrm{TF}}.\label{intro:liminf}
\end{align}
All limits are over integers.  The inner limits hold $m$ fixed; no
convergence in $Z$ at a fixed $m$ is assumed.
\end{theorem}

\begin{theorem}
\label{phase:main}
For each fixed \(M>0\) and \(0<\mathfrak a<M\), there is
\(\eps_0=\eps_0(M,\mathfrak a)>0\) such that
\(\mathcal U_{\eps_0}\) contains a dense \(G_\delta\) subset
\(\mathcal G\) for which every \(\mathcal M_d\), \(d\in\mathcal G\),
has no future \(C^1\) extension in the sense of
Definition~\ref{phase:extension}.
\end{theorem}

\begin{theorem}[Gigli's characterization]
\label{main:equivalence}
Let \(n\ge2\) be an integer, let \(\kappa\in\R\), and let \((M,d)\)
be a complete separable metric space. The following conditions are
equivalent.
\begin{enumerate}[label=\textup{(\Alph*)}]
\item \((M,d)\) is an \(n\)-dimensional Alexandrov space with curvature
bounded below by \(\kappa\).
\item With \(m=\mathcal H^n_d\), the space \((M,d,m)\) has full support,
is \(\RCD((n-1)\kappa,n)\), and satisfies
\begin{equation}
\label{eq:main-curvature}
R(X,Y,Y,X)(f)\ge
\kappa\int_M f\bigl(|X|^2|Y|^2-\langle X,Y\rangle^2\bigr)\dd m
\end{equation}
for every \(X,Y\in\TestV(M)\) and every nonnegative \(f\in\Test(M)\).
\end{enumerate}
The \(\RCD\) condition is unreduced, and the test classes and
curvature sign are exactly those defined above.
\end{theorem}

\begin{theorem}[The $2$-converse]\label{thm:main-converse}
For every elliptic curve $E/\Q$ with $c_2(E)\in\{0,1\}$,
\[
 a(E)=r(E)=c_2(E),\qquad \Sha(E/\Q)\text{ is finite}.
\]
\end{theorem}

\begin{theorem}[Goldfeld's analytic density conjecture]\label{thm:main-density}
For every elliptic curve $E/\Q$ and each $j\in\{0,1\}$,
\[
 \lim_{X\to\infty}
 \frac{\#\{d\in\mathcal D(X):a(E^{(d)})=j\}}{\#\mathcal D(X)}
 =\frac12.
\]
Consequently the twists of analytic rank at least two have density zero.
For a density-one set of signed squarefree parameters $d$, the analytic
and Mordell--Weil ranks of $E^{(d)}$ agree and its whole
Tate--Shafarevich group is finite.
\end{theorem}

\begin{theorem}[The $2$-converse]\label{thm:main-converse}
For every elliptic curve $E/\Q$ with $c_2(E)\in\{0,1\}$,
\[
 a(E)=r(E)=c_2(E),\qquad \Sha(E/\Q)\text{ is finite}.
\]
\end{theorem}

\begin{theorem}[Goldfeld's analytic density conjecture]\label{thm:main-density}
For every elliptic curve $E/\Q$ and each $j\in\{0,1\}$,
\[
 \lim_{X\to\infty}
 \frac{\#\{d\in\mathcal D(X):a(E^{(d)})=j\}}{\#\mathcal D(X)}
 =\frac12.
\]
Consequently the twists of analytic rank at least two have density zero.
For a density-one set of signed squarefree parameters $d$, the analytic
and Mordell--Weil ranks of $E^{(d)}$ agree and its whole
Tate--Shafarevich group is finite.
\end{theorem}

\begin{theorem}[Finite-dimensional fluctuation limit]\label{thm:main}
Under \Cref{ass:kinetic}, the centered Gaussian generalized field
\(\zeta\) with weak equation
\begin{equation}\label{eq:fluctuating-equation}
 \dd\zeta_t(\phi)=\zeta_t(A_t\phi)\,\dd t+\dd W_t(\phi)
\end{equation}
is well defined by its backward mild form on a scale of tests with small
Gaussian growth. Its initial field is independent of \(W\), and
\begin{align}
 \E[\zeta_0(\phi)\zeta_0(\psi)]
   &=\int_{\R^6}f_0\phi\psi\,\dd z,\label{eq:initial-covariance}\\
 \E[W_t(\phi)W_s(\psi)]
   &=\int_0^{t\wedge s}C_r(\phi,\psi)\,\dd r.\label{eq:noise-covariance}
\end{align}
The Gaussian noise \(W\) has independent increments. For every integer
\(m\ge1\), fixed times \(t_1,\ldots,t_m\in[0,T]\), and real tests
\(\phi_1,\ldots,\phi_m\in C_c^\infty(\R^6)\),
\begin{equation}\label{eq:main-convergence}
 \bigl(\zeta_{t_1}^\eps(\phi_1),\ldots,
       \zeta_{t_m}^\eps(\phi_m)\bigr)
 \quad\Longrightarrow\quad
 \bigl(\zeta_{t_1}(\phi_1),\ldots,
       \zeta_{t_m}(\phi_m)\bigr)
 \qquad(\eps\downarrow0).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed real $0<\delta<1/3$, there is a deterministic
polynomial-time algorithm $R_\delta$ that maps each explicitly encoded
Boolean $3$-CNF formula $\phi$ to a nonempty finite simple undirected
unweighted graph $G_\phi$ such that
\[
 \begin{array}{ll}
 \phi\text{ is satisfiable}
   &\Longrightarrow G_\phi\text{ is three-colorable},\\[2pt]
 \phi\text{ is unsatisfiable}
   &\Longrightarrow \alpha(G_\phi)<\delta\,|V(G_\phi)|.
 \end{array}
\]
The running time and explicit output size are polynomial in the ordinary
binary encoding length of $\phi$. Their constants and polynomial degree
may depend on the fixed $\delta$, but not on $\phi$.
The coloring in the first implication covers every vertex and is not
supplied with the graph.
\end{theorem}

\begin{theorem}[Hellinger conjecture]\label{thm:main}
For every \(n\ge1\), every Boolean function
\(f:\{-1,1\}^n\to\{-1,1\}\), and every \(\rho\in[-1,1]\), writing \(m=\E f\), one has
\begin{equation}\label{eq:main}
H(m)-\E H(T_\rho f)\le1-H(\rho).
\end{equation}
Both expectations are with respect to the uniform probability measure.
\end{theorem}

\begin{theorem}\label{thm:main}
There is no algorithm which, given a polynomial
$f\in\Z[X_1,\ldots,X_n]$, with $n$ part of the input, decides whether
$f$ has a zero in $\Q^n$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is no algorithm which, given a polynomial
$f\in\Z[X_1,\ldots,X_n]$, with $n$ part of the input, decides whether
$f$ has a zero in $\Q^n$.
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a real homogeneous hyperbolic polynomial whose closed
hyperbolicity cone has no finite semidefinite lift.
\end{theorem}

\begin{theorem}\label{thm:main}
For every multiplier $W$ as above, the Banach space $X_W$ is infinite
dimensional and has no equivalent AUC norm.
For the exponential and Gaussian-square laws, the inherited norms satisfy
\begin{align}
 \whdelta_{X_{\mathrm{exp}}}(t)
 &\ge \frac{7t}{30}c(10/t)>0 &&(t>0),\label{eq:main-exp}\\
 \whdelta_{X_{\mathrm{sq}}}(t)
 &\ge\frac{\PP\bigl(|G|\ge4\sqrt2(2+\sqrt2)/t\bigr)}{8}>0
 &&(t>0),\label{eq:main-sq24}\\
 \whdelta_{X_{\mathrm{sq}}}(t)
 &\ge\frac{\PP\bigl(|G|\ge8\sqrt6/t\bigr)}{4}>0
 &&(t>0).\label{eq:main-sq12}
\end{align}
\end{theorem}

\begin{theorem}\label{thm:spheres}
For every integer $n\ge2$ and every smooth Riemannian metric on the standard
smooth sphere $S^n$, there are infinitely many prime closed geodesics with
pairwise different images.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $(u,K)$ be a reduced absolute minimizer of
\eqref{eq:original-energy} in a bounded Lipschitz domain
$\Omega\subset\mathbb R^2$, with $g\in L^\infty(\Omega)$.
Every $x\in K$ has an interior neighborhood in which $K$ has one of the
following forms, with $C^{1,\alpha}$ arcs for some $\alpha>0$:
\begin{enumerate}[label=\textup{(\roman*)},nosep]
 \item a single embedded arc with $x$ in its interior;
 \item a single embedded arc ending at $x$;
 \item three embedded arcs meeting only at $x$, with pairwise angles
       $120$ degrees.
\end{enumerate}
Moreover, for every open $U\Subset\Omega$,
\begin{equation}\label{eq:component-finiteness}
 \#\{C\in\pi_0(K):C\cap U\ne\varnothing\}<\infty,
\end{equation}
where $\pi_0(K)$ denotes the set of global connected components of $K$.
\end{theorem}

\begin{theorem}[Circle-domain uniformization]\label{thm:main}
Every nonempty connected open set $G\subset\Chat$ is conformally equivalent
to a circle domain.
\end{theorem}

\begin{theorem}
\label{thm:main}
There is an absolute constant $C<\infty$ such that
\[
 \Var(H_n)\le Cn\qquad(n\ge3).
\]
There are also absolute constants $c>0$ and $n_0$ such that
$\Var(H_n)\ge cn$ for $n\ge n_0$. In particular,
$\Var(H_n)=\Theta(n)$ as $n\to\infty$.
\end{theorem}

\begin{theorem}
\label{thm:main}
There are separable real Banach spaces \(X,Y\) and a bijection
\(\Psi:X\to Y\) such that, for every \(s,t\in X\),
\begin{equation}
\label{eq:main-bounds}
 \frac4{21}\|s-t\|_X
 \le \|\Psi(s)-\Psi(t)\|_Y
 \le \frac{76}{25}\|s-t\|_X.
\end{equation}
The space \(X\) contains a linearly isometric copy of \(c_0(\ell_2)\), while
\(Y\) contains no closed subspace linearly isomorphic to
\(c_0(\ell_2)\). In particular, \(X\) and \(Y\) are not linearly
isomorphic.
\end{theorem}

\begin{theorem}[Log abundance]\label{thm:main}
Let $(X,B)$ be a normal projective log canonical pair over an algebraically
closed field of characteristic zero. Assume that $B$ is an effective rational
divisor and $K_X+B$ is $\Q$-Cartier. If $K_X+B$ is nef, then some positive
Cartier multiple of it is generated by global sections.
\end{theorem}

\begin{theorem}[Logarithmic variation]\label{thm:main}
Let $f:U\to V$ be a projective surjective morphism with connected fibers
between smooth connected quasi-projective complex varieties.
Assume $\kbar(V)\geq0$, and let $F$ be its geometric generic fiber.
Then
\begin{equation}\label{eq:main}
 \kbar(U)\geq\kappa(F)+\max\{\kbar(V),\Var(f)\}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Assume the deterministic reference-model estimates of
\cite{ReferenceIsing}, at the scopes stated in Section~\ref{sec:reference}.
There is $\eps_0>0$ such that for every fixed $\eps\in(0,\eps_0)$,
\begin{equation}\label{eq:main-limit}
 \lim_{r\to\infty,\,r\in\N}
       \frac{\log R_\eps(r)}{\log\log r}=\frac14.
\end{equation}
The critical inverse temperature in \eqref{eq:quenched-correlation} is
the physical value \eqref{eq:critical-definition}; it is the unique positive
solution of
\begin{equation}\label{eq:critical-curve}
 \sinh\bigl(2\beta(1-\eps)\bigr)
 \sinh\bigl(2\beta(1+\eps)\bigr)=1.
\end{equation}
\end{theorem}

\begin{theorem}[Squared-length polygon mass]\label{thm:polygon-moment}
For every $\eta>0$ there is $C_\eta<\infty$ such that, for $H\ge1$,
\[
 \sum_{\substack{[P]\ \operatorname{diam}P\le H}}
       \rho_{\rm v}^{|P|}|P|^2\le C_\eta H^{2/3+\eta}.
\]
The sum is over the simple unoriented polygon translation classes just
defined.
\end{theorem}

\begin{theorem}[Fixed-length mass and covering exponents]\label{thm:main}\label{09_fast_paths:fixed-length}
For every $\delta>0$ and $k>0$, there are constants $C_{\delta,k}<\infty$ and $n_0(\delta,k)$ such that, for every integer $n\ge n_0(\delta,k)$, an event of $\Prob_n$-probability at least $1-C_{\delta,k}n^{-k}$ has all the following properties:
\begin{align}
 n^{3/4-\delta}&\le D(\gamma)\le n^{3/4+\delta},\label{eq:main-diameter}\\
 n^{-\delta}\min\{n,s^{4/3}\}
 &\le M_\gamma(z,s)\le n^{\delta}\min\{n,s^{4/3}\},\label{eq:main-mass}\\
 n^{-\delta}(1+ns^{-4/3})
 &\le \mathcal N_\gamma(s)\le n^{\delta}(1+ns^{-4/3}).\label{eq:main-cover}
\end{align}
The last two bounds hold simultaneously for every $z\in V(\gamma)$ and every real $s\in[1,n]$ (with $z$ relevant only to \eqref{eq:main-mass}).
\end{theorem}

\begin{theorem}\label{thm:main}
For every $\eps>0$, two $n\times n$ complex matrices can be multiplied
using $O_\eps(n^{9/4+\eps})$ arithmetic operations. In particular,
$\omega\leq9/4$.
\end{theorem}

\begin{theorem}\label{thm:main}
Let $X/k$ be a smooth integral projective variety over an algebraically
closed field of characteristic $p>0$, with $\dim X=n\ge3$, and let $L$
be ample. There is an integer $r_0=r_0(X,L)$ such that
\[
 \varepsilon_r(X,L)=\left(\frac{L^n}{r}\right)^{1/n}
 \qquad\text{for every integer }r\ge r_0.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
A uniform deterministic algorithm returns exactly all vertices from
which Max can force~\eqref{eq:objective} against every Min strategy.
For an absolute constant $C>0$, it uses at most
\[
                     2^{C(\log_2(L+2))^2}
\]
bit operations. The number of distinct priorities and the magnitudes
of the rewards are unrestricted.
\end{theorem}

\begin{theorem}\label{thm:main}
The real space $\ell_1$ satisfies
\[
 N_2(\ell_1)\leq12\sqrt{21}.
\]
\end{theorem}

\begin{theorem}[Metric and measure convergence]\label{thm:main}\label{tree:thm:main}
For each fixed \(q\in(0,4)\) in the FK ensemble, and for the spanning-tree
ensemble, there are deterministic positive numbers \(a_n\to0\) such that
\[
          (V(M_n),a_nd_n,\mu_n)
             \xrightarrow[n\to\infty]{\mathrm{law}}
          (S,D_h,\mu_h)
\]
in Gromov--Hausdorff--Prokhorov topology on compact metric probability
spaces modulo measure-preserving isometry. The limit has the parameter
specified above. Convergence holds through all positive integers \(n\);
the root and decoration are forgotten.
\end{theorem}

\begin{theorem}\label{thm:four}
Each of the four completed spaces $X_K$ is a separable infinite-dimensional
real Banach space. For $K\in\{K_{\rm s},K_{\rm p},K_{\rm a},K_{\rm g}\}$
and $0<t<1$,
\begin{equation}\label{eq:common-bound}
 \widehat\delta_{X_K}(t)\ge\sqrt{1+t^2/4}-1.
\end{equation}
None of these spaces admits an equivalent AUC norm.
\end{theorem}

\begin{theorem}\label{rec:main}\label{rec:joined-root-stability}
For $N=N_\Sigma$ on $X_\Sigma$, or $N=N_J$ on $X_J$, one has
\begin{equation}\label{rec:sum-modulus}
 \widehat\delta_N(t)\ge t^3/128\qquad(0<t<1).
\end{equation}
For $X_0$, a finite initial set $H$, a vector $x$ supported in $H$, and
$z\in F_H\setminus\{0\}$, one has
\begin{equation}\label{rec:equal-estimate}
 \frac{N_0(x+z)+N_0(x-z)}2\ge N_0(x)
 +\frac{N_0(z)^3}{8(2N_0(x)+N_0(z))^2}.
\end{equation}
Each of $X_\Sigma,X_0,X_J$ admits no equivalent AUC norm.
\end{theorem}

\begin{theorem}\label{thm:main-tail}\label{mol:prop:joint-budget}
Let $Y$ be either the finite-height forest dual $X=J^*$ or the
infinite-height coordinate predual $B_\infty$. For every finite
ancestral $H$, every $x,y\in Y$ with $x=P_Hx$, and every $R\ge0$
with $\|x+y\|,\|x-y\|\le R$,
\begin{equation}\label{eq:main-squared-tail}
 \|Q_Hy\|\le2\sqrt{R^2-\|x\|^2}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There are an absolute constant $c>0$ and capacity instances $C^{(j)}$
on $n_j\to\infty$ vertices, with $\GL(C^{(j)})>0$, such that
\[
\frac{\OPT(C^{(j)})}{\GL(C^{(j)})}
\ge c\,\frac{\sqrt{\log n_j}}{(\log\log n_j)^3}
\]
for all sufficiently large $j$. The demand is one between every pair
of distinct vertices.
\end{theorem}

\begin{theorem}
\label{thm:main}
Let $G$ be an infinite connected locally finite quasi-transitive
undirected graph. If $\pc(G)<1$, then
\[
 \PP_{\pc(G)}(\text{there is an infinite open cluster})=0.
\]
Equivalently, $\PP_{\pc(G)}(|C_x|=\infty)=0$ for every vertex $x$.
\end{theorem}

\begin{theorem}\label{thm:pair}
There exist closed connected aspherical topological four-manifolds
$M$ and $N$ that are homotopy equivalent but not homeomorphic.
Their common fundamental group is word-hyperbolic.
\end{theorem}

\begin{theorem}\label{thm:main}
Every real Banach space with Markov type $p$ for at least one $p>1$
is superreflexive.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist real scalar functions $\gamma_0,\gamma_1\in
L^\infty(B(0,3);\R)$ and constants $0<c<C<\infty$ such that
\begin{enumerate}[label=\textup{(\roman*)},itemsep=2pt]
\item $c\leq\gamma_j\leq C$ almost everywhere, for $j=0,1$;
\item both conductivities equal $1$ in a neighborhood of the boundary;
\item $\abs{\{x:\gamma_0(x)\ne\gamma_1(x)\}}>0$;
\item $\Lambda_{\gamma_0}=\Lambda_{\gamma_1}$ as bounded operators
from $H^{1/2}(\partial B(0,3))$ to $H^{-1/2}(\partial B(0,3))$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Nonsimple nuclear regularity]
\label{thm:main}
\label{intro:regularity}
Let $A$ be a separable nuclear complex $C^*$-algebra with no nonzero
elementary ideal subquotients. The following conditions are equivalent:
\begin{enumerate}
\item $\nucdim(A)<\infty$;
\item $A\cong A\otimes\Z$;
\item $\nucdim(A)\le1$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Orbifold subadditivity]\label{main:orbifold}
Let $X$ be a smooth compact connected complex manifold in Fujiki
class $\mathcal C$, let $\Delta$ be a rational SNC boundary, and
let $f:X\to Y$ be a surjective holomorphic map with connected
fibers onto a normal compact irreducible complex space.
For a very general smooth fiber $F$, put $\Delta_F=\Delta|_F$.
Then
\begin{equation}\label{main:inequality}
 \kappa(X,K_X+\Delta)
 \geq\kappa(F,K_F+\Delta_F)+\kappa(f\mid\Delta).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Every finite simple undirected graph that is cubic, bipartite,
planar, and \(3\)-vertex-connected has a Hamiltonian cycle.
\end{theorem}

\begin{theorem}[Tree inequality]
\label{thm:tree-inequality}
Fix a finite rooted tree with the end identifications and order-$20$ metric bounds of Section~\ref{ell:setup}. Let $(g_j,L^{(j)},M_j)$ satisfy the compact vertex convergence, the same uniform half-end and root-end bounds, and Equation~\eqref{eq:tree-ricci-error} through order $10$, with every $L_e^{(j)}\to\infty$ and $M_j\to0$. Then, in physical root units,
\begin{equation}
                         E(g_j)=o(M_j).
 \label{ell:little-oh}
\end{equation}
For an index with $M_j=0$, the assertion means $E(g_j)=0$. The little-oh is taken for this fixed tree; it does not assert a power exponent uniform over different trees.
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed rational $\delta\in(0,1)$ there are an integer $q=q(\delta)\ge2$
and a deterministic polynomial-time reduction from $3$-SAT to 2-to-1 games
with alphabets $[2q]$ and $[q]$ such that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item a satisfiable formula produces a game of value $1$;
\item an unsatisfiable formula produces a game of value at most $\delta$.
\end{enumerate}
The output contains a nonempty explicit list of unweighted edge occurrences
and an explicit table for every projection map.
Every table has exactly two preimages for each right answer.
The polynomial running-time bound is in the ordinary binary input length;
its degree and constants may depend on the fixed $\delta$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every integer $n\ge4$ and every convex body $K\subset\R^n$,
\begin{equation}\label{eq:main}
 \frac{|\Pi K|}{|K|^{n-1}}
 \ge \kappa_{n-1}^{\,n}\kappa_n^{\,2-n}.
\end{equation}
Equality holds if and only if $K=a+TB_2^n$ for some $a\in\R^n$ and some
invertible linear map $T$.
\end{theorem}

\begin{theorem}\label{thm:main}
There are a deterministic Turing machine $G$ and fixed positive integers $C,k$ with the following property. Given $1^n,1^s$, where $n,s\geq1$, the machine outputs a finite list $\mathcal H_{n,s}$ of $n$-tuples of rational square matrices, in at most $C(n+s+1)^k$ bit operations. The entire output, with signed binary numerators and positive binary denominators, has at most $C(n+s+1)^k$ bits. For every nonzero admissible rational formula $\Phi$ in $n$ variables of size at most $s$, some tuple in $\mathcal H_{n,s}$ is a defined evaluation of $\Phi$ with invertible value.

The same list works for all such formulas, regardless of the bit lengths of their rational constants or their inverse depth. The generator receives no formula, oracle, randomness, or advice.
\end{theorem}

\begin{theorem}\label{thm:main}
Fix an integer $q\ge2$ and constants $J,\Delta>0$. There are constants
$C,c>0$, depending only on $q,J,\Delta$, with the following property.
For every $L\ge2$, consider any Hermitian Hamiltonian
\begin{equation}\label{eq:model}
 H=\sum_{v\in\Lambda_L}h_v+\sum_{e\in E(\Lambda_L)}h_e,
 \qquad \norm{h_v},\norm{h_e}\le J,
\end{equation}
where each summand is supported on its designated site or edge.
Suppose that $H$ has a unique normalized ground vector $\Omega$, up to
phase, with ground energy $E_0$, and
\begin{equation}\label{eq:global-gap}
 H-E_0I\ge\Delta\bigl(I-|\Omega\rangle\langle\Omega|\bigr).
\end{equation}
Then there is a nonzero PEPS $\Phi$ on the same grid with maximum bond
dimension at most $CL^c$ such that
\begin{equation}\label{eq:target-error}
 \min_{\theta\in\mathbb R}
 \left\|\frac{\Phi}{\norm{\Phi}}-e^{i\theta}\Omega\right\|
 \le L^{-1}.
\end{equation}
\end{theorem}

\begin{theorem}
\label{thm:main}
There are an orthonormal sequence
$\Psi_j\in\Dom(H)$ and real numbers $E_j>0$ tending to infinity such that
\[
 H\Psi_j=E_j\Psi_j.
\]
In particular, $\sigma_{\mathrm p}(H)\cap(0,\infty)$ is infinite.
\end{theorem}

\begin{theorem}\label{thm:main}
There are infinitely many primes $p$ such that $p-1$ is squarefree
and $\Omega(p-1)$ is even. In particular, there are infinitely many
such primes under either convention for counting prime factors.
\end{theorem}

\begin{theorem}\label{thm:primitive-root}\label{thm:main}
For every admissible integer $a$, there are constants $c_a>0$ and
$x_a\ge2$ such that, for every real $x\ge x_a$,
\[
 \#\{p\text{ prime}:x<p<2x,\ p\nmid a,\ \ord_p(a)=p-1\}
       \ge c_a\frac{x}{(\log x)^2}.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For the zero-field SK model~\eqref{eq:sk-model},
\begin{equation}\label{eq:main-result}
 \lim_{p\to\infty}Q_p=\Pstar.
\end{equation}
Equivalently, for every $\varepsilon>0$ there exist a finite integer $p$ and
deterministic real vectors $\gamma,\beta\in\R^p$, independent of $n$ and $J$,
such that $v_p(\gamma,\beta)\ge\Pstar-\varepsilon$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every integer $a\ge2$, every integer $b\ge a(a-1)$, and every
finite-dimensional complex vector space $V$, the map
$\mu_{a,b,V}$ in \eqref{eq:map} is surjective. Equivalently, $A_b=R_b$.
\end{theorem}

\begin{theorem}
\label{main:intro}
There is an absolute integer $K_0$ such that, for every integer
$k\ge K_0$ and every integer $r\ge2$,
\[
 W_r(k)>k^{c k\lfloor\log_2r\rfloor},
 \qquad c=10^{-5}.
\]
\end{theorem}

\begin{theorem}[Outer-color dichotomy]\label{dichotomy:main}
For every sufficiently large $k$, the coloring $c_0$ from
\Cref{outer:pullback} has the following property. Every cyclic
progression $n_j=n_0+jd$, $0\le j<k$, with $d\ne0$ in $G$,
satisfies at least one of these alternatives:
\begin{enumerate}[label=\textup{(\roman*)}]
 \item each bit occurs among $c_0(n_0),\ldots,c_0(n_{k-1})$
 at least $\gamma k$ times;
 \item there are $A,B\in\R^D$ such that
 $\tilde y(n_j)=A+jB$ for all $0\le j<k$.
\end{enumerate}
The threshold on $k$ is absolute.
\end{theorem}

\begin{theorem}\label{thm:main}
For every $a>0$, every bounded continuous real function $f$ on $\R^3$,
and every $\eps>0$, there is $\rho_0(a,f,\eps)>0$ with the following
property. Fix $0<\rho<\rho_0$ and put $\eta=\rho a^3$. For every
sequence $N_j,L_j\longrightarrow\infty$ with
$N_j/L_j^3\longrightarrow\rho$,
\begin{equation}\label{intro:main-limit}
 \limsup_{j\to\infty}\ \sup_{\Gamma\in\mathcal G_{N_j,L_j,a}}
 \left|
 \frac{1}{N_j\sqrt\eta}
 \sum_{\substack{k\in(2\pi/L_j)\Z^3\\k\ne0}}
 f\!\left(\frac{k}{\sqrt{8\pi\rho a}}\right)n_{\Gamma,L_j}(k)
       -\int_{\R^3}f\,\dd\nu_{\mathrm{Bog}}
 \right|\le\eps.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
For every potential $v$ satisfying the assumptions above and every
$\epsilon>0$, there is $\rho_0(v,\epsilon)>0$ such that, for every fixed
$0<\rho<\rho_0(v,\epsilon)$ and every sequence
$N_k,L_k\to\infty$ with $N_k/L_k^3\to\rho$,
\[
 \limsup_{k\to\infty}\ \sup_{\Gamma\in\mathcal G^v_{N_k,L_k}}
 \left|\frac{1-B_\Gamma}{\sqrt{\rho a_v^3}}
                       -\frac8{3\sqrt\pi}\right|\le\epsilon.
\]
\end{theorem}

\begin{theorem}\label{ap:main}
For each fixed integer $k\ge3$ there are constants
$C_k,c_k,\varepsilon_k>0$ such that, for every $N\ge2$,
\begin{equation}\label{ap:density-bound}
 r_k(N)\le C_kN\exp\bigl(-c_k(\log N)^{\varepsilon_k}\bigr).
\end{equation}
Equivalently, there is $A_k\ge1$ such that an $\alpha$-dense subset
of $[N]$ contains a nonconstant $k$-term progression whenever
\begin{equation}\label{ap:threshold}
 \log N\ge A_k\bigl(2+\log(1/\alpha)\bigr)^{A_k},
 \qquad 0<\alpha\le1.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Let \(C\subset\Acal_{2,\Qbar}\) be a reduced irreducible closed Hodge-generic algebraic curve. Then
\[
 \Sigma_{\mathrm{QM}}(C)=
 \bigl\{s\in C(\Qbar):
   \End^0(A_s)\text{ is an indefinite quaternion division algebra over }\Q
 \bigr\}
\]
is finite.
\end{theorem}

\begin{theorem}
\label{thm:main}
Let \(h\) be a minimal homeomorphism of an infinite compact metrizable
space \(X\). Then
\begin{equation}
\label{eq:main}
\rc\bigl(C(X)\rtimes_h\Z\bigr)=\frac12\mdim(X,h)
\qquad\text{in }[0,\infty].
\end{equation}
\end{theorem}

\begin{theorem}\label{main:decomposition}
For every \(X,G,D,\ell\) as above, the natural addition maps
\begin{equation}\label{intro:decomposition}
 \bigoplus_{\mathcal O}C_{D,\mathcal O,\mathbb Q}
       \xrightarrow{\ \sim\ }C_{D,\mathbb Q},
 \qquad
 \bigoplus_{\mathcal O}C_{D,\mathcal O,\ell}
       \xrightarrow{\ \sim\ }C_{D,\ell}
\end{equation}
are isomorphisms. The sums range over the nilpotent orbits of \(\Gd\).
\end{theorem}

\begin{theorem}\label{thm:main}
Let $(M_n,A_n)$ have law \eqref{eq:fk-law}, and let $a_n>0$ be any
deterministic sequence with $a_n\to0$ such that
\begin{equation}\label{eq:assumed-ghp}
 (V_n,a_nd_n,\mu_n)\ \Longrightarrow\ (S,D_h,\mu_h)
\end{equation}
in Gromov--Hausdorff--Prokhorov law. Given the map, start $r$ independent
simple random walks $X^{n,1},\ldots,X^{n,r}$ independently from $\mu_n$.
Given $h$, start $r$ independent Liouville Brownian motions
$B^{h,1},\ldots,B^{h,r}$ independently from $\mu_h$, with the convention
\eqref{eq:continuum-form}. For every fixed integer $r\ge1$,
\begin{equation}\label{eq:main-limit}
 \left(\overline M_n,a_nd_n,\mu_n;
       (\overline X^{n,j}_{nt})_{t\ge0,\,1\le j\le r}\right)
 \ \Longrightarrow\
 \left(S,D_h,\mu_h;
       (B^{h,j}_t)_{t\ge0,\,1\le j\le r}\right)
\end{equation}
in the curve-decorated Gromov--Hausdorff--Prokhorov topology.
\end{theorem}

\begin{theorem}[Regular-trace smoothing]\label{ten:lowplanes:main}
There is an absolute $P\ge2$ such that for every dyadic $n\ge2$,
\begin{equation}\label{ten:lowplanes:eq:1}
 \operatorname{Tr}_{\rm reg}|Q_n|^P\le1+n^{-10}.
\end{equation}
If $v$ is an integer with $2v\ge P$, then $v$ independent sweeps have total-variation distance at most $\frac12n^{-5}$ from uniform, from every deterministic initial deck. Here $\|\mu-\nu\|_{\rm TV}=\tfrac12\sum_g|\mu(g)-\nu(g)|$.
\end{theorem}

\begin{theorem}\label{intro:main}
Under Assumption~\ref{intro:characteristic}, for every prime
$\ell\ne\operatorname{char}(\mathbb F_q)$ and every closed invariant
$Y\subset\Nhat$, the natural map
\begin{equation}\label{intro:main-map}
E\otimes_\Q\bigl(\cA_\Q\cap\cF_Y\cA_E\bigr)
\xrightarrow{\ \sim\ }\cF_Y\cA_E
\end{equation}
is an isomorphism. The intersection is taken inside $\cA_E$.
\end{theorem}

\begin{theorem}
\label{thm:parity}
Fix positive integers $d,k,C$ and a real $0<\varepsilon\le1/2$.
There is an integer $n_0=n_0(d,k,C,\varepsilon)$ such that,
for every $n\ge n_0$, every allowed circuit of depth at most $d$
on at most $C(n+1)^k$ total qubits has an input $x\in\{0,1\}^{n}$ on which its answer equals
$\Parity_n(x)$ with probability strictly less than $1/2+\varepsilon$.
\end{theorem}

\begin{theorem}\label{thm:main}
Every type $\mathrm{II}_1$ factor $M$ with separable predual is
generated by two self-adjoint elements. Equivalently, there is an
$x\in M$ such that $M=W^*(x)$.
\end{theorem}

\begin{theorem}\label{thm:relative-generation}
Let $P\subset M$ be an irreducible inclusion of type $\mathrm{II}_1$
factors, with $M$ of separable predual. The set
\[
 \{u\in\mathcal U(M):W^*(P,u)=M\}
\]
is a dense $G_\delta$ subset of the unitary group $\mathcal U(M)$
for the trace $2$-norm topology.
\end{theorem}

\begin{theorem}\label{rec:coherent-main}
There is an absolute $p_*\ge1$ such that, for every dyadic $n$ and
every irreducible type $\lambda\vdash n$,
\begin{equation}\label{rec:coherent-unit-moment}
 D_\lambda\Tr\!\left(((B_n^*B_n)|_{V_\lambda})^{p_*}\right)\le1.
\end{equation}
Consequently $\|B_n|_{V_\lambda}\|\le D_\lambda^{-1/(2p_*)}$. The moment in the display is the Schatten power $2p_*$, because $\operatorname{Tr}(B_n^*B_n)^{p_*}=\|B_n\|_{2p_*}^{2p_*}$.
\end{theorem}

\begin{theorem}[Weighted sweep moments]\label{thm:weighted}
There are positive weights $W_\lambda$, an absolute finite $p_*$, and real
exponents $2\le p_d\le p_*$ such that, for every $d\ge1$ and every
$\lambda\vdash2^d$,
\begin{equation}\label{eq:weighted-main}
 D_\lambda^{3/4}\le W_\lambda\le D_\lambda,
 \qquad W_\lambda\|K_d(\lambda)\|_{p_d}^{p_d}\le1.
\end{equation}
Consequently $\|K_d(\lambda)\|_{\rm op}\le D_\lambda^{-3/(4p_*)}$.
\end{theorem}

\begin{theorem}\label{intro:main}
For every fixed integer $s\ge6$ there is a constant $C_s>0$ such that,
for every $\varepsilon>0$ and every sufficiently large integer $t$,
\[
 \frac{t^{s-1}}{(\log t)^{s-2+\varepsilon}}
 \le r(s,t)
 \le C_s\frac{t^{s-1}}{(\log t)^{s-2}}.
\]
In particular,
\[
 \lim_{t\to\infty}
 \frac{(s-1)\log t-\log r(s,t)}{\log\log t}=s-2.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For every $1/2<\gamma<3/2$ and every nonnegative
$W\in L^{\gamma+1/2}(\R)$,
\begin{equation}\label{eq:main}
 \Tr(H_{-W})_-^\gamma
 \le 2\left(\frac{\gamma-1/2}{\gamma+1/2}\right)^{\gamma-1/2}
       L_{\gamma,1}^{\cl}\int_\R W^{\gamma+1/2}.
\end{equation}
The constant is optimal and equals $L_{\gamma,1}^{(1)}$.
More precisely, if $r=(\gamma-1/2)^{-1}$, equality is attained by
$W(x)=(r+1)\sech^2(rx)$.
\end{theorem}

\begin{theorem}\label{main:stability}
For every \(K,Y\) as above there is a finite constant \(C(K,Y)\) such that
\[
 \|T_\mu-T_\nu\|_{L^2(\rho)}
 \le C(K,Y)\,W_2(\mu,\nu)^{1/3}
 \qquad\bigl(\mu,\nu\in\Prob(Y)\bigr).
\]
The targets may be atomic, singular, or absolutely continuous. The
exponent \(1/3\) cannot be replaced by any larger exponent in general,
even for \(K=Y=[-1,1]^d\) and targets with exactly three atoms.
\end{theorem}

\begin{theorem}[Sharp soft-channel contraction]
\label{main:soft}
For every finite $n\ge0$, every $u:\Omega_n\to[-1,1]$, and
$-1\le\rho\le1$,
\begin{equation}
 I(T_\rho u)
 \le\psi\!\left(|\rho|\,\psi^{-1}(I(u))\right).
 \label{main:interpolation}
\end{equation}
The inverse is the nonnegative increasing branch on $[0,L]$.
For $n\ge1$, every soft coordinate $u(x)=a x_i$, $|a|\le1$,
attains equality.
\end{theorem}

\begin{theorem}[Sharp integral filling]\label{thm:main}
Let $X$ be a proper CAT(0) space and $n\ge2$ an integer.
Every compactly supported $T\in\I_n(X)$ with $\partial T=0$ admits a
compactly supported $S\in\I_{n+1}(X)$ such that
\begin{equation}\label{eq:main}
 \partial S=T,\qquad
 \M(S)\le c_n\M(T)^{(n+1)/n}
 =\frac{\M(T)^{(n+1)/n}}
 {(n+1)^{(n+1)/n}\omega_{n+1}^{1/n}}.
\end{equation}
There is no restriction on the dimension of $X$ or on the integer
multiplicities of the currents. The coefficient is optimal.
\end{theorem}

\begin{theorem}
\label{thm:main}
There are finite constants $\beta_0,c,C$, with $0<c<C$, such that for
every $\beta\ge\beta_0$ the periodic square measures have a unique local
limit, and its full transfer gap satisfies
\begin{equation}
\label{eq:target}
 c\sqrt\beta\,e^{-\pi\beta}\le\gap(\beta)
            \le C\sqrt\beta\,e^{-\pi\beta}.
\end{equation}
There are also a fixed dyadic blocking factor $L$, a fixed large
terminal coupling $H$, and finite integers $N_0,M_0$ with the following
property. For every $N\ge N_0$ one can choose a bare coupling
$\beta_N$ whose exact $N$-step block transformation has terminal
kinetic coupling $H$, and
\begin{equation}
\label{eq:depth-bounds}
 \frac{\log2}{M_0L^N}\le\gap(\beta_N)
                  \le\frac{\log8}{L^N}.
\end{equation}
The same bounds hold uniformly for terminal couplings in a fixed small
interval about $H$, after increasing $M_0$ and $N_0$ if necessary.
\end{theorem}

\begin{theorem}[Sharp matrix inequality]\label{thm:main}
For every $1/2<\gamma<3/2$, every finite $m\ge1$, and every $W$ satisfying
\eqref{eq:potential-class},
\begin{equation}\label{eq:main-bound}
 \Tr(H_W)_-^\gamma\le C_\gamma\int_\R\tr(W(x)^{\gamma+1/2})\,dx,
 \qquad
 C_\gamma=
 \left(\frac{\gamma-1/2}{\gamma+1/2}\right)^{\gamma-1/2}
 \frac{\Gamma(\gamma+1)}{\sqrt\pi\,\Gamma(\gamma+3/2)}.
\end{equation}
The constant is optimal in every matrix dimension. With
$r=(\gamma-1/2)^{-1}$, it is attained by
\begin{equation}\label{eq:extremal-potential}
 W(x)=\diag\big((r+1)\sech^2(rx),0,\ldots,0\big).
\end{equation}
\end{theorem}

\begin{theorem}
\label{thm:main}
There exist a simply connected closed K\"ahler manifold $(M,\omega)$
of complex dimension $1666$ and a smooth one-periodic Hamiltonian $H$
such that
\[
 c_1(TM)(\pi_2(M))=\Z,
\]
every fixed point of $\phi_H^1$ is nondegenerate, and
\begin{align*}
 \#\Fix(\phi_H^1)
 &=\#\Fix_0(\phi_H^1;H)
  =\beta_{\Z}^{\mathrm{cyc}}(M)=1\,872\,232,\\
 \SM(M)&=\beta_{\Z}^{\mathrm{cyc}}(M)+32=1\,872\,264.
\end{align*}
\end{theorem}

\begin{theorem}\label{thm:main}
Every finitely generated group \(G\) with decidable word problem admits
an injective homomorphism into a nontrivial simple group \(H\) of type
\(\Finfty\).
\end{theorem}

\begin{theorem}\label{thm:main}
For every integer $n\ge1$ and every recursively enumerable set
$S\subseteq\NN^n$, there are an integer $m\ge1$ and a polynomial
$P\in\ZZ[A_1,\ldots,A_n,W_1,\ldots,W_m]$ such that, for every $a\in\NN^n$,
\[
 \#\{w\in\NN^m:P(a,w)=0\}=
 \begin{cases}1,&a\in S,\\0,&a\notin S.\end{cases}
\]
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a nonquadratic function $u\in C^\infty(\R^{10})$
with $D^2u$ positive definite at every point such that
\[
 \sum_{i,j=1}^{10}U^{ij}\partial_{ij}
       (\det D^2u)^{-11/12}=0
 \quad\hbox{on }\R^{10},
 \qquad U=\det(D^2u)(D^2u)^{-1}.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
Every closed smooth Riemannian surface $(M,g)$ admits a $C^\infty$ isometric
immersion into $(\R^4,\delta_4)$, where $\delta_4=\sum_{i=1}^4 dx_i^2$.
\end{theorem}

\begin{theorem}\label{thm:main}
Set $\kap=1/10000$. For every fixed $\beta>1$,
\begin{align*}
 \PP_{J,\,x_0\sim\pi^J}
  \left\{d^J\bigl(x_0,\exp(n^\kap)\bigr)>\frac14\right\}
  &\longrightarrow1,\\
 \PP_{J,\,x_0\sim\pi^J}
  \left\{d_{\mathrm{disc}}^J
       \bigl(x_0,\lfloor\exp(n^\kap)\rfloor\bigr)>\frac14\right\}
  &\longrightarrow1.
\end{align*}
\end{theorem}

\begin{theorem}\label{thm:main}
For every $0\ne u\in\V$,
\[
\grad u(x)\ne0\qquad(x\in\Omega).
\]
In particular,
\begin{equation}\label{eq:hotspots}
\min_{y\in\partial\Omega}u(y)<u(x)<\max_{y\in\partial\Omega}u(y)
\qquad(x\in\Omega).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
A countable discrete group is strongly Ulam stable if and only if it is
amenable.
\end{theorem}

\begin{theorem}\label{main:theorem}
Let $\Omega,\Lambda\subset\R^3$ be nonempty bounded connected open sets, let $1\le p\le2$, and let $f:\Omega\to\Lambda$ be a homeomorphism in $W^{1,p}(\Omega;\R^3)$. There exist $C^\infty$ diffeomorphisms $f_j:\Omega\to\Lambda$, each belonging to $W^{1,p}(\Omega;\R^3)$, such that
\begin{equation}\label{main:convergence}
\int_\Omega\bigl( |f_j-f|^p+|Df_j-Df|^p\bigr)\,dx\longrightarrow0.
\end{equation}
\end{theorem}

\begin{theorem}\label{main:theorem}\label{ha:approximation}
Let $\Omega,\Lambda\subset\R^3$ be bounded domains, let $2<p<\infty$,
and let $f:\Omega\to\Lambda$ be a homeomorphism in
$W^{1,p}(\Omega;\R^3)$. There exist $C^\infty$ diffeomorphisms
$f_j:\Omega\to\Lambda$, each belonging to
$W^{1,p}(\Omega;\R^3)$, such that
\begin{equation}\label{main:convergence}
\int_\Omega\bigl( |f_j-f|^p+|Df_j-Df|^p\bigr)\,dx\longrightarrow0.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Fix $1<p<\infty$, $p\ne2$, and put
\[
 \gamma(p)=
 \begin{cases}
  2-p,&1<p<2,\\
  1-2/p,&2<p<\infty.
 \end{cases}
\]
For every $D>1$ there is a constant $C_{p,D}<\infty$ such that, for
every integer $n\ge2$,
\begin{equation}\label{eq:main-bounds}
 \frac{\log n}{\log(1+2D)}
 \le d_p(n,D)
 \le \exp\!\bigl(C_{p,D}(\log n)^{\gamma(p)}\bigr).
\end{equation}
For exact embeddings,
\begin{equation}\label{eq:exact-bounds}
 \left\lfloor\frac{n-1}{4}\right\rfloor^2
 \le d_p(n,1)\le\binom n2\qquad(n\ge9).
\end{equation}
Consequently,
\[
 \lim_{n\to\infty}\frac{\log d_p(n,D)}{\log n}
 =\begin{cases}0,&D>1,\\2,&D=1.\end{cases}
\]
\end{theorem}

\begin{theorem}
\label{thm:main}
Set $k=2^{75}$. For every integer $N\ge1$, every $p\in(0,1)$, and every
family $\mathcal D\subseteq2^{[N]}$,
\[
\mu_p(\mathcal D)\ge1-\frac1k
\quad\Longrightarrow\quad
E_k(\mathcal D)\text{ is }p\text{-small}.
\]
\end{theorem}

\begin{theorem}\label{intro:main}
For every parameter \eqref{intro:parameter} satisfying the preceding hypotheses, there is a nonzero locally constructible perverse geometric $E$-adic sheaf $M$ on $\cA$ with
\[
 \SS(M)\subset\Lambda_D.
\]
For every finite set $I$ and every family $(V_i)_{i\in I}$, it has isomorphisms
\begin{equation}\label{intro:eigen}
 \Hecke_{I,(V_i)}(M)
 \simeq M\boxtimes\Bigl(\mathop{\boxtimes}_{i\in I}(V_i)_\rho\Bigr)
 \qquad\text{on }\cA\times U^I,
\end{equation}
natural in the representations and coherent for the tensor unit, convolution, permutations, and fusion on every collision diagonal. These isomorphisms use the relative normalization above.
\end{theorem}

\begin{theorem}\label{thm:main}
Suppose that a smooth almost complex structure \(J\) on a closed
connected smooth real four-manifold \(X\) is tamed by a symplectic
form. Then there is a smooth symplectic form compatible with \(J\).
\end{theorem}

\begin{theorem}\label{thm:main}
Suppose that a smooth almost complex structure \(J\) on a closed
connected smooth real four-manifold \(X\) is tamed by a symplectic
form. Then there is a smooth symplectic form compatible with \(J\).
\end{theorem}

\begin{theorem}\label{thm:main}
Let $k$ be an algebraically closed field of characteristic zero, and let $(X,B)$ be a projective lc pair of dimension four with rational boundary. No $\mathbb Q$-factoriality or pseudo-effectivity is assumed.
\begin{enumerate}[label=\textup{(\roman*)}]
\item Every negative extremal ray at every stage has the contraction and, when birational, a positive model required by Definition~\ref{def:program}.
\item Every program of Definition~\ref{def:program} starting from $(X,B)$ has finitely many birational steps, for every sequence of permitted choices.
\item Every maximal program ends either at a projective lc pair with nef adjoint, or at a Mori fibre space: a projective contraction with connected fibres, relative Picard number one, lower-dimensional normal base, and relatively ample negative adjoint.
\end{enumerate}
An already nef input has a zero-step completed program.
\end{theorem}

\begin{theorem}\label{thm:main}
For every prime $p$, every finite group $G$, and every $p$-block $B$ of $G$,
\[
                  l(B)=|W_p(B)|.
\]
\end{theorem}

\begin{maintheorem}[Regular-lifespan kinetic limit]\label{thm:main}
Let $\Phi$ satisfy Assumption~\ref{pre:potential}, and let $\beta>0$.
Let $f_0\ge0$ be a $C^1$ probability density on $\R^3\times\R^3$ such that
\begin{equation}\label{intro:data-bound}
 \|f_0\|_{\mathrm{Bol},2\beta}
 +\|\nabla_xf_0\|_{\mathrm{Bol},2\beta}<\infty.
\end{equation}
Fix $0<T<\infty$ for which the equation
\begin{equation}\label{intro:boltzmann}
 (\partial_t+v\cdot\nabla_x)f=Q_\Phi(f,f),
 \qquad f|_{t=0}=f_0,
\end{equation}
has a nonnegative classical probability-density solution satisfying
\begin{equation}\label{intro:solution-bound}
 \sup_{0\le t\le T}\sup_{x,v}
 e^{2\beta|v|^2}f(t,x,v)<\infty.
\end{equation}
Start the exact Newtonian process from the grand-canonical law
\eqref{pre:model}. For its scaled factorial densities
$F_s^\varepsilon$, defined in \eqref{pre:factorial}, every fixed
integer $s\ge1$ satisfies
\begin{equation}\label{intro:chaos}
 \lim_{\varepsilon\downarrow0}\;
 \sup_{0\le t\le T}
 \bigl\|F_s^\varepsilon(t)-f(t)^{\otimes s}\bigr\|_
 {L^1((\R^3\times\R^3)^s)}=0.
\end{equation}
\end{maintheorem}

\begin{theorem}\label{thm:main}
Every smooth connected complex projective Fano variety of dimension six
with nef tangent bundle is rational homogeneous.
\end{theorem}

\begin{theorem}\label{thm:main}
For every odd positive integer $N$, every irreducible component of
$\Spec T_2(N)$ has dimension exactly $4$.
\end{theorem}

\begin{theorem}[Explicit cover gap]
\label{thm:gap}
For every fixed integer \(m\geq4\), there is a deterministic
polynomial-time reduction from \(\mathrm{3SAT}\) to finite simple
undirected unweighted graphs with the following guarantees:
\[
\begin{array}{ll}
\text{the formula is satisfiable}
 &\Longrightarrow\quad
 \tau(G)<\left(\dfrac12+\dfrac1m\right)|V(G)|,\\[6pt]
\text{the formula is unsatisfiable}
 &\Longrightarrow\quad
 \tau(G)>\left(1-\dfrac1m\right)|V(G)|.
\end{array}
\]
The output lists all vertices and edges explicitly.
\end{theorem}

\begin{theorem}\label{thm:main}
Fix any Grothendieck coherator \(\mathcal C\).
Let \(X\) be a cellular \(\mathcal C\)-infinity-groupoid, let \(n\ge0\),
and let \(a:D_n\to X\) be any cell.  In the pushout square
\[
\begin{tikzpicture}[baseline=(current bounding box.center),
                   node distance=1.25cm and 2.2cm,>=Stealth]
\node (a) {\(D_n\)};
\node (b) [right=of a] {\(D_{n+1}\)};
\node (c) [below=of a] {\(X\)};
\node (d) at (b |- c) {\(X^+\)};
\draw[->] (a) -- node[above] {\(s_n\)} (b);
\draw[->] (a) -- node[left] {\(a\)} (c);
\draw[->] (b) -- (d);
\draw[->] (c) -- node[below] {\(i\)} (d);
\end{tikzpicture}
\]
where \(s_n\) is the source inclusion, the map \(i:X\to X^+\)
is a weak equivalence.
\end{theorem}

\begin{theorem}[$p$-adic exclusion]\label{thm:main}
Let \(n\geq1\) be an integer and \(p\) a prime. Every jointly continuous
action of \(\Zp\) on a connected Hausdorff second-countable topological
\(n\)-manifold without boundary has nonzero kernel. Consequently the
action factors through a finite quotient of \(\Zp\).
\end{theorem}

\begin{theorem}[The Hilbert--Smith conjecture]\label{cor:lie}
Let \(n\geq1\). A locally compact second-countable Hausdorff group
acting faithfully and jointly continuously on a connected Hausdorff
second-countable topological \(n\)-manifold without boundary is a Lie
group.
\end{theorem}

\begin{theorem}\label{thm:main}
For every \(\varepsilon>0\) there exists a finite constant
\(C_\varepsilon\) such that, for every \(0<\delta<1\) and every
\(f\in L^3(\R^3)\),
\[
\|K_\delta f\|_{L^3(S^2)}
\le C_\varepsilon\delta^{-\varepsilon}
     \|f\|_{L^3(\R^3)}.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
Let $A$ be a nonzero unital separable complex $C^*$-algebra, and let
$\omega$ be any free ultrafilter on $\N$. Then
\[
 F_\omega(A)\text{ has no characters}
 \quad\Longleftrightarrow\quad A\cong A\otmin\Z.
\]
\end{theorem}

\begin{theorem}\label{main:theorem}
Under \eqref{model:integrability}--\eqref{model:positivity}, the thermodynamic
limit exists and
\begin{equation}\label{main:formula}
 \lim_{N\to\infty}F_N=\inf_{r\ge0}\Phi_r.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main-consistency}
If $\ZF$ is consistent, then so is $\ZF+\PP+\ACwo+\neg\AC$.
\end{theorem}

\begin{theorem}[Global maximal AH Penrose inequality]\label{thm:main}
Under \eqref{eq:decay}--\eqref{eq:future-trapping}, the completeness,
one-end, and smoothness assumptions above, and the future-timelike
condition \eqref{eq:invariant-mass}, one has
\begin{equation}\label{eq:main-inequality}
 m_{\AH}(g)\ge\frac12\bigl(r_A+r_A^3\bigr),
 \qquad r_A=\sqrt{\frac{A_{\min}(S;g)}{4\pi}}.
\end{equation}
The coefficient is sharp: equality holds for every positive-mass
time-symmetric Schwarzschild--anti-de Sitter exterior bounded by its
minimal horizon.
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed $k\ge1$ and every bounded continuous function
$F:[0,1]^k\to\R$,
\begin{equation}\label{eq:main-law}
 \lim_{x\to\infty}\frac1{\pi(x)-1}
     \sum_{\substack{3\le p\le x\\p\text{ prime}}}
       F\bigl(V_1(p),\ldots,V_k(p)\bigr)
 =\E F(L_1,\ldots,L_k).
\end{equation}
The limit holds through all real $x$ and uses ordinary equal
weighting of the primes.
\end{theorem}

\begin{theorem}\label{thm:main}
Every finite-order Hecke $L$-function over $K$ has no zeros in the half-plane $\Rea s>11/12$. Thus every Dirichlet $L$-function, including $\zeta(s)$, has no zeros for $\Rea s>11/12$.
\end{theorem}

\begin{theorem}\label{thm:main}
Every finite-order Hecke $L$-function over
$F=\mathbb Q(\sqrt{-3})$ has no zero in $\Re s>7/8$.
The same holds for every Dirichlet $L$-function, including $\zeta(s)$.
A pole at $s=1$ for a principal character is allowed.
\end{theorem}

\begin{theorem}\label{thm:main}
For the channel \eqref{eq:broadcast-channel}, if $d\lambda^2\leq1$, then
\[
 \lim_{n\to\infty}a_n(d,\lambda)=0
\]
in each of the following models:
\begin{enumerate}
 \item the rooted $d$-ary tree, for every integer $d\geq2$;
 \item the Poisson$(d)$ Galton--Watson tree, for every real $d>0$.
\end{enumerate}
In particular, the assertion includes $d\lambda^2=1$.
\end{theorem}

\begin{theorem}
\label{thm:main}
There is an absolute constant \(C>0\) such that, for every
\(\varepsilon>0\), all sufficiently large integers \(t\) satisfy
\[
 \frac{t^4}{(\log t)^{3+\varepsilon}}
 \ \le\ r(5,t)\ \le\
 C\frac{t^4}{(\log t)^3}.
\]
The threshold for \(t\) may depend on \(\varepsilon\).
Consequently,
\[
 \lim_{t\to\infty}
 \frac{4\log t-\log r(5,t)}{\log\log t}=3.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
Let \(n\ge2\) be an integer, let \(p,q>0\), and let \(A,B\in\R\).
Suppose that
\begin{equation}\label{eq:subcritical}
 \frac{n+A}{p+1}+\frac{n+B}{q+1}>n-2.
\end{equation}
There are no functions
\[
 u,v\in C^2(\R^n\setminus\{0\})\cap C(\R^n),
 \qquad u(x)>0,\quad v(x)>0\quad(x\in\R^n),
\]
satisfying Equation~\eqref{eq:system} at every \(x\ne0\).
\end{theorem}

\begin{theorem}[Unique Games Theorem]\label{thm:ugc}
For every fixed \(\varepsilon,\delta\in(0,1/2)\), there are an integer
\(s\ge1\) and a deterministic polynomial-time reduction from
\(\mathrm{3SAT}\) to explicit unweighted Unique Games instances
\(G_\varphi\) over \(K=\F_2^s\) such that
\[
\begin{aligned}
 \varphi\text{ satisfiable}
 &\quad\Longrightarrow\quad \val(G_\varphi)\ge1-\varepsilon,\\
 \varphi\text{ unsatisfiable}
 &\quad\Longrightarrow\quad \val(G_\varphi)\le\delta.
\end{aligned}
\]
The graph is simple and bipartite, and every constraint is a translation
\(a(v_e)=a(u_e)+c_e\) of \(K\). The alphabet, the degree of the
running-time polynomial, and its constants depend only on
\(\varepsilon,\delta\).
\end{theorem}

\begin{theorem}\label{thm:abelianity}
Let \(X\) be a connected smooth compact K\"ahler manifold of arbitrary
complex dimension. If \(X\) is special, then \(\pi_1(X)\) has an abelian
subgroup of finite index. Equivalently, \(X\) has a connected finite
unramified holomorphic cover with abelian fundamental group.
\end{theorem}

\begin{theorem}\label{thm:main}
For a positive integer \(n\), a real circulant Hadamard matrix of
order \(n\) exists if and only if \(n\in\{1,4\}\).
\end{theorem}

\begin{theorem}
\label{thm:main}
The following problem is EXPTIME-complete under deterministic
polynomial-time many-one reductions: given a nonempty finite simple
undirected uncolored graph $G$ by its adjacency matrix and a positive
integer $k$ in binary, decide whether $\WLdim(G)\le k$.
Here dimension one uses ordinary neighbor color refinement, and
dimensions at least two use the joint-update rule described above.
\end{theorem}

\begin{theorem}[Joint critical universality]\label{thm:main}
For the finite law \eqref{intro:fk-weight}, there is a deterministic sequence $a_n>0$, with $a_n\to0$, such that through all positive integers $n$,
\begin{equation}\label{intro:joint-limit}
 \bigl((\phi_n)_*m_n,K_n(a_n),\Gamma_n\bigr)
 \ \xrightarrow{\ d\ }\
 \bigl(\mu_h^{\rm crit},
       \{(z,w,D_h(z,w)):z,w\in S^2\},\Gamma\bigr).
\end{equation}
Here $(H,\mu_h^{\rm crit})\sim\mathsf P_{\rm crit}$, the area topology is weak convergence, the distance-graph topology is the Hausdorff topology just defined, and the loop topology is convergence by $\eps$-matchings. All nesting and multiplicities are retained. In the same joint convergence,
\begin{equation}\label{intro:flag-mesh}
 \max_{T\ \text{flag of }X_n}\diam_\rho\phi_n(T)
       \ \xrightarrow{\ \Prob\ }0.
\end{equation}
The metric normalization is the one fixed in Theorem~\ref{thm:continuum}; changing it by a deterministic factor changes $a_n$ by that factor.
\end{theorem}

\begin{theorem}\label{thm:main}
For the model \eqref{eq:xy-law} and the threshold
\eqref{eq:critical-definition},
\[
 \lim_{\substack{n\to\infty\\n\in\N,\ n\ge2}}
       \frac{\log C_{b_c}(n)}{\log n}=-\frac14.
\]
Equivalently, for every \(\eps>0\) there is \(n_0<\infty\) such that
\[
 n^{-1/4-\eps}\le C_{b_c}(n)\le n^{-1/4+\eps}
 \qquad(n\ge n_0).
\]
\end{theorem}

\begin{theorem}\label{thm:main}
Every nonzero one-homogeneous global minimizer of \eqref{eq:energy}
in \(\R^d\), \(1\leq d\leq6\), is flat. There is a nonflat
one-homogeneous global minimizer in \(\R^7\). Consequently,
\[
  d_*=7.
\]
\end{theorem}

\begin{theorem}
\label{thm:main}
For all positive integers $m,n$,
\[
 \crn(K_{m,n})=d_m d_n.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed $S\in\{\tfrac12,1,\tfrac32,\ldots\}$,
\[
 \lim_{\beta\to\infty}(\beta S)^{5/2}
       \bigl[S-m_S(\beta)-n_S^{\mathrm{sw}}(\beta)\bigr]=0.
\]
\end{theorem}

\begin{theorem}[Gaussian Ising perceptron]\label{thm:main}
For every $\alpha>0$ and every bounded Borel $f:\mathbb R\to\mathbb R$,
\begin{equation}\label{thm:formula}
 \lim_{N\to\infty}\mathbb E p_N(f)
 =\mathcal P_f(\alpha)
 :=\inf_{q\in\mathcal Q}\{\alpha V_f(q)+S_{\mathrm I}(q)\}.
\end{equation}
Moreover, $p_N(f)$ converges to $\mathcal P_f(\alpha)$ in probability.
The variational value is finite. In particular, the conclusion holds for
$f=\beta\phi$ at every $\beta>0$ and every bounded continuous activation
$\phi$, without symmetry, concavity, or a smallness restriction.
\end{theorem}

\begin{theorem}\label{thm:main}
The irrationality exponent of \(\pi\) is \(2\). More precisely, for every
real \(\nu>2\), there is an integer \(Q(\nu)\) such that
\[
\left|\pi-\frac pq\right|\ge q^{-\nu}
\qquad(p\in\ZZ,\ q\in\ZZ,\ q\ge Q(\nu)).
\]
\end{theorem}

\begin{theorem}[Even logarithmic Brunn--Minkowski inequality]
\label{thm:main}
Let $n\ge1$ and let $K,L\subset\R^n$ be convex bodies satisfying
$K=-K$ and $L=-L$. For every $0\le\lambda\le1$,
\begin{equation}\label{eq:main}
 \left|\mathcal W[h_K^{1-\lambda}h_L^\lambda]\right|
 \ge |K|^{1-\lambda}|L|^\lambda.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There is an absolute constant $C$ such that, for every pair of complex
functions $F,G\in L^3(\R^2)$,
\[
 \|B_*(F,G)\|_{L^{3/2}(\R^2)}
 \le C\|F\|_{L^3(\R^2)}\|G\|_{L^3(\R^2)}.
\]
The supremum is over both finite hard truncation endpoints.
\end{theorem}

\begin{theorem}[Computer-assisted]\label{thm:main}
Under the arithmetic and compiler conditions in
Appendix~\ref{sec:rounding}, the fresh complete execution documented in
Section~\ref{execute:observed} certifies that there are no four pairwise mutually unbiased orthonormal bases in
$\C^6$. Consequently, $N(6)=3$.
\end{theorem}

\begin{theorem}\label{thm:mean}
For every elliptic curve \(E/\Q\),
\[
 \lim_{Y\to\infty}\frac{1}{\#\mathcal D(Y)}
     \sum_{d\in\mathcal D(Y)}a(E^{(d)})=\frac12.
\]
\end{theorem}

\begin{theorem}\label{thm:mean}
For every elliptic curve \(E/\Q\),
\[
 \lim_{Y\to\infty}\frac{1}{\#\mathcal D(Y)}
     \sum_{d\in\mathcal D(Y)}a(E^{(d)})=\frac12.
\]
\end{theorem}

\begin{theorem}[Nonmaximal anti-de Sitter Penrose Inequality]\label{thm:main-numerical}
Let $(\Omega,g,K)$ satisfy Definition~\ref{def:setup-data}, the same
future boundary condition $H+\tr_{TS}K\le0$ on every component, and
the future-timelike metric mass condition in Definition~\ref{def:setup-mass}.
Then
\begin{equation}\label{eq:main-penrose}
 m_{\AH}(g)\ge
 \sqrt{\frac{A_{\min}(S)}{16\pi}}
 \left(1+\frac{A_{\min}(S)}{4\pi}\right)
 =\frac{r_A+r_A^3}{2}.
\end{equation}
The coefficient is sharp. No maximality assumption, restriction on the
compact topology or boundary genera, or outermostness hypothesis is required.
\end{theorem}

\begin{theorem}[Original-data equality]\label{thm:main-rigidity}
Assume in addition the connected horizon hypotheses of
Definition~\ref{def:setup-horizon}. Equality in Equation~\ref{eq:main-penrose}
holds if and only if the original pair $(g,K)$ is realized by a smooth
proper spacelike embedding of $\Omega$, with boundary, into the smooth
maximally extended Schwarzschild--anti-de Sitter spacetime of parameter
exactly $M=m_{\AH}(g)$. Its interior lies in one black-hole exterior;
its boundary maps diffeomorphically onto a full smooth spacelike
cross-section of that exterior's future event horizon, with the
bifurcation sphere also allowed; and its unique end reaches that
exterior's conformal infinity. The embedding induces both $g$ and $K$
with the future-normal convention of Equation~\ref{eq:setup-expansion}.
\end{theorem}

\begin{theorem}\label{thm:main}
For the Hamiltonians \eqref{eq:main-H}, the ground state is unique for
every even $L\ge60$, and
\begin{align}
 \gamma_L&>\frac4{105}\log\frac{80}{79}
     &&\text{for every even }L\ge60,\label{eq:gap60}\\
 \gamma_L&>\frac{\log20}{784}
     &&\text{for every even }L\ge2304.\label{eq:gap2304}
\end{align}
Consequently
\[
 \Delta_1\ge\frac{\log20}{784}>0.
\]
The spectral conclusions also hold for any simultaneously similar
spin-one realization satisfying the same commutator and Casimir
normalizations.
\end{theorem}

\begin{theorem}[Reverse logarithmic Kodaira inequality]\label{thm:upper-bound}
Under these hypotheses,
\begin{equation}\label{eq:upper-bound}
 \kappa(X,L_X)\leq\kappa(Y,L_Y)+\kappa(F,L_F).
\end{equation}
If either term on the right is $-\infty$, then
$H^0(X,mL_X)=0$ for every $m>0$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every $n\ge2$ and every finite simple graph $H$ with $h=e(H)\ge1$
edges and at most $n$ vertices,
\begin{equation}\label{eq:stronger}
 \pc(n,H)\le
 \min\{1,\;2048\ee^{50}\pE(n,H)(1+\log_2 h)\}.
\end{equation}
In particular,
\[
 \pc(n,H)\le6144\ee^{50}\pE(n,H)\log_2 n.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For the symmetric Bernoulli matrix \(A_n\),
\[
 \Pr(\det A_n=0)=\left(\frac12+o(1)\right)^n
                =2^{-n+o(n)}
 \qquad\text{as }n\to\infty.
\]
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed $p\in(0,1)\setminus\{1/2\}$,
\[
 \lim_{n\to\infty}\Prob\bigl(\det A_n^{(p)}=0\bigr)^{1/n}
   =p^2+(1-p)^2.
\]
\end{theorem}

\begin{theorem}[The enclosing-area Penrose inequality]\label{thm:main}
Let $(\Omega^n,g,K)$ be the smooth one-ended exterior specified above,
with integrable constraint densities, finite ADM limits, dominant
energy condition and weakly future trapped boundary. Suppose
\[
 g-\delta=O_6(r^{-q}),\qquad K=O_5(r^{-1-q}),\qquad
 \frac{n-2}{2}<q<n-2,
\]
and assume $E>|P|_\delta$ and $A_{\min,g}(S)>0$. Then
\begin{equation}\label{eq:setting:main}
 m\geq\frac12\left(\frac{A_{\min,g}(S)}{\omega_{n-1}}
                 \right)^{\frac{n-2}{n-1}}.
\end{equation}
The coefficient and exponent are sharp in each dimension $n\geq3$.
\end{theorem}

\begin{theorem}[Charged spacetime Penrose inequality]\label{thm:numerical}
Let the data satisfy Definition~\ref{def:data}, and suppose
$\theta_+\le0$ on every component of $S$. Then $E>|P|$, the invariant
ADM mass $m=\sqrt{E^2-|P|^2}$ is positive, and
\begin{equation}\label{eq:main-inequality}
 E\ge\sqrt{|P|^2+Q^2},\qquad
 m\ge Q,\qquad
 r_A\le m+\sqrt{m^2-Q^2}.
\end{equation}
The same conclusion holds if, on each boundary component, one fixes
either the condition $H+\operatorname{tr}_S K\le0$ or the condition
$H-\operatorname{tr}_S K\le0$.
\end{theorem}

\begin{theorem}[Spherical magnetization law]\label{thm:main}
For each fixed $S$ there is a finite $\beta_0(S)$ such that, for every
fixed finite $\beta\ge\beta_0(S)$, one has $m=m_{S,\beta}>0$ and
\begin{equation}\label{eq:spherical-law}
 \lim_{\substack{L\to\infty\\L\text{ even}}}
  \left\langle
     \exp\!\left(\frac1V\sum_{a=1}^3t_aM_L^a\right)
  \right\rangle_{\beta,L}
   =\frac1{4\pi}\int_{\mathbb S^2}e^{m t\cdot n}\dd\sigma(n)
   =\frac{\sinh(m|t|)}{m|t|}
 \qquad(t\in\R^3).
\end{equation}
Here $\sigma$ is surface-area measure on $\mathbb S^2$, and the quotient
at $t=0$ is interpreted as $1$. In addition,
\begin{equation}\label{eq:second-moment-law}
 \lim_{\substack{L\to\infty\\L\text{ even}}}
   \frac1{V^2}\sum_{x,y\in\Lambda_L}
          \langle S_x\cdot S_y\rangle_{\beta,L}=m^2.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Fix $\alpha>0$, $M=\lfloor\alpha N\rfloor$, and $f\in C_b(\R)$. Suppose the law of $A_N$ is invariant under left and right orthogonal multiplication and, in probability,
\begin{equation}\label{eq:spectralhyp}
\frac1{r_N}\sum_{r=1}^{r_N}\delta_{s_{N,r}}\Longrightarrow\nu,
\qquad
\max_{r\le r_N}\operatorname{dist}(s_{N,r},\supp\nu)\longrightarrow0,
\end{equation}
where $\nu$ is a deterministic compactly supported probability measure on $[0,\infty)$. Then $F_N(A_N,f)$ converges in probability and in mean to a deterministic value $F_{\alpha,\nu}(f)$.

\pagebreak[3]
Here is its formula. Approximate the singular slots in operator norm by finitely many positive values $s_1,\ldots,s_h$ whose multiplicities satisfy $n_j/M\to p_j>0$. Thus $\sum_jp_j=\min(1,1/\alpha)$. Put $v_j=\alpha p_j$, and, if $\alpha<1$, add an input null block with $v_0=1-\alpha$. Let $\mathcal I=\{1,\ldots,h\}$ when $\alpha\ge1$ and $\mathcal I=\{0,1,\ldots,h\}$ otherwise. The variable $\rho_i$ is the fraction of the input squared norm assigned to block $i$. The value for this finite approximation is
\begin{equation}\label{eq:radialformula}
\sup_{\substack{\rho_i>0\\\sum_{i\in\mathcal I}\rho_i=1}}
\left\{
\frac12\sum_{i\in\mathcal I}v_i\log\frac{\rho_i}{v_i}
+\alpha P_p^f\left(\left(\frac{s_j^2\rho_j}{\alpha}\right)_{j=1}^h\right)
\right\}.
\end{equation}
The limit of \eqref{eq:radialformula} as the spectral mesh tends to zero is $F_{\alpha,\nu}(f)$. Blocks with zero limiting proportion are not used in \eqref{eq:radialformula}; the no-outlier assumption ensures the required approximations with positive limiting proportions.
\end{theorem}

\begin{theorem}\label{thm:main}
For every integer $n\ge1$ and every origin-symmetric convex body
$K\subset\R^n$,
\begin{equation}\label{eq:main-inequality}
 |K|\,|K^\circ|\ge\frac{4^n}{n!}.
\end{equation}
Equality holds if and only if $K$ is a linear Hanner body.
\end{theorem}

\begin{theorem}[Weak inhomogeneous Duffin--Schaeffer]
\label{thm:main}
Let $\gamma\in\mathbb R$ be fixed, and let
$\psi:\mathbb N\to[0,\infty)$ be finite-valued. If
\begin{equation}\label{eq:main-divergence}
  \sum_{q=1}^{\infty}\frac{\phi(q)}q\,\psi(q)=\infty,
\end{equation}
then, for Lebesgue-almost every $x\in\mathbb R$, the inequality
\[
  \|qx-\gamma\|<\psi(q)
\]
holds for infinitely many positive integers $q$.
\end{theorem}

\begin{theorem}\label{thm:main}
For every fixed $s>0$, one has $F_n(s)\longrightarrow0$ as
$n\longrightarrow\infty$.
\end{theorem}

\begin{theorem}\label{thm:main}
Thompson's group \(F\) is not amenable.
\end{theorem}

\begin{theorem}[Threshold parallel repetition]\label{thm:main}
There is a universal constant $\kappa_0>0$ such that the following holds.
Let $G$ be any finite two-player one-round game with Boolean acceptance
predicate and entangled value $v=\omega^*(G)<1$. For every
$0<\delta<1-v$, every integer $k\ge1$, and every finite-dimensional
joint strategy for $k$ repetitions,
\begin{equation}\label{eq:main}
 \Pr\!\left[W_k\ge\lceil(v+\delta)k\rceil\right]
 \le \exp\!\left(-\frac{\kappa_0\delta^5}
                         {1+\log d}\,k\right).
\end{equation}
The same inequality holds for the supremum over those strategies.
\end{theorem}

\begin{theorem}[The direct unital comparison route]\label{u:thm:main}
Let $A$ be a simple, separable, unital, infinite-dimensional nuclear
$C^*$-algebra with strict comparison in the preceding sense.
Then $A\cong A\otimes\Z$. When $T(A)\ne\varnothing$, the proof constructs
uniform property $\Gamma$ directly.
\end{theorem}

\begin{theorem}
\label{thm:main}
There are a uniform deterministic Turing machine and an absolute constant
$C$ such that, on every valid input described above, the machine outputs
exactly $U$ in at most
\[
                       2^{C(\log_2(L+2))^2}
\]
bit operations. The bound includes input reading, exact rational
arithmetic, and output. Vertices of value zero are included.
\end{theorem}

\begin{theorem}[Two-step linear monodromy]\label{thm:linear}
Let $V$ be a connected smooth special complex quasi-projective variety.
For every positive integer $d$ and every representation
$\rho:\pi_1(V)\to\GL_d(\C)$, the image $\rho(\pi_1(V))$ has a subgroup
of finite index and nilpotency class at most two.
\end{theorem}

\begin{maintheorem}[Uniform Cartier sections]\label{thm:main}
For every integer $d>0$ and every real number $\epsilon>0$, there is a real number $\tau=\tau(d,\epsilon)>0$ with the following property. Let $(X,B)$ be an $\epsilon$-lc rational pair of dimension $d$, and let $f:X\to Z$ be a Fano type contraction of normal integral quasi-projective varieties with $\dim Z>0$. Suppose that $-(K_X+B)$ is nef over $Z$. For every closed point $z\in Z$, there are an open neighbourhood $U$ of $z$ and a nonzero effective Cartier divisor $D$ on $U$, with $z\in\Supp D$, such that
\[
\bigl(f^{-1}(U),B|_{f^{-1}(U)}+\tau f^*D\bigr)
\quad\text{is log canonical.}
\]
\end{maintheorem}

\begin{maintheorem}[Birational klt complements]\label{thm:birational}
For each $d>0$ and $\epsilon>0$, there is a positive integer $n=n(d,\epsilon)$ such that the following holds. Let $X$ be an $\epsilon$-lc rationally Gorenstein variety of dimension $d$, and let $f:X\to Z$ be a birational Fano type contraction with $-K_X$ nef over $Z$. For every closed $z\in Z$, there is an effective rational divisor $\Delta$ over a neighbourhood of $z$ such that $(X,\Delta)$ is klt there and $n(K_X+\Delta)$ is Cartier and linearly trivial there, after shrinking the neighbourhood.
\end{maintheorem}

\begin{theorem}[Uniform interior estimate]\label{thm:main}
For every integer $d\ge3$ there are constants $\alpha_d\in(0,1/3]$ and
$C_d<\infty$ such that every bounded infinity-harmonic function
$u\in C(B_1)$, where $B_1\subset\R^d$, belongs to
$C^{1,\alpha_d}(B_{1/2})$ and satisfies
\[
 \|\nabla u\|_{L^\infty(B_{1/2})}
       +[\nabla u]_{C^{0,\alpha_d}(B_{1/2})}
       \le C_d\osc_{B_1}u.
\]
\end{theorem}

\begin{theorem}[Uniform pluricanonical degree]\label{thm:main}
For each integer $d\geq1$ there is an integer $m(d)>0$ such that, over
every algebraically closed field of characteristic zero, the complete
system $|m(d)K_X|$ defines the Iitaka fibration of every smooth integral
projective $d$-fold $X$ with $\kappa(X)\geq0$.
\end{theorem}

\begin{theorem}[Uniform scalar-disorder stability]\label{thm:main}
There are constants $\lambda_*>0$, $\Delta_*>0$, and
$N_*<\infty$ such that, for every $N\ge N_*$, every real
bounded measurable $\varphi$ on $S_{3(N-1)}$ with
$\|\varphi\|_\infty\le1$, and every real
$|\lambda|\le\lambda_*$,
\begin{equation}\label{eq:intro-stability}
 E_1(N,\lambda,\varphi)-E_0(N,\lambda,\varphi)\ge\Delta_*.
\end{equation}
In particular the perturbed ground state is unique.
\end{theorem}

\begin{theorem}[Uniform canonical index]\label{thm:fourfold-index-zero}
There is a positive integer $N_4$ such that $N_4K_X\sim0$ for every
normal projective klt complex fourfold $X$ with $K_X\sim_\Q0$.
\end{theorem}

\begin{theorem}\label{thm:main}
There is an absolute constant $c>0$ such that every real zero
$\beta\in(0,1)$ of every primitive nonprincipal real Dirichlet
$L$-function of conductor $q\ge3$ satisfies
\begin{equation}\label{eq:main}
 (1-\beta)\log q\ge c.
\end{equation}
\end{theorem}

\begin{theorem}[Finite bridge estimates]\label{thm:finite-bridges}
There are constants $c,C>0$ such that, for every sufficiently large integer $h$,
\begin{align}
 c h^{-1/4}&\le B_h\le C h^{-1/4},\label{eq:bridge-mass}\\
 \sum_{\gamma\in\mathcal B_h}\ell(\gamma)w(\gamma)&\le C h^{13/12},\label{eq:bridge-first-moment}\\
 B_h\{\ell\ge c h^{4/3}\}&\ge c h^{-1/4}.\label{eq:bridge-long-fraction}
\end{align}
Moreover, for every $h\ge1$ and $x\ge0$,
\begin{equation}\label{eq:bridge-diameter}
 B_h\{\diam\gamma>x\}\le C(1+x)^{-1/4}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There are constants $A>0$, $\sigma>0$, and $\lambda\in(0,1/2]$, independent
of $D,a,b$, such that the model \eqref{eq:model} has
\[
 \gamma_\delta\Longrightarrow\mathrm{SLE}_4(D;a,b),\qquad
 \frac{h_\delta-\E h_\delta}{\sigma}
       \Longrightarrow\mathrm{GFF}_D
\]
in the stated curve metric and as random distributions, respectively.
The constants and limiting mean are
\begin{align}
 v&=2/\sqrt3,&\sigma^2&=(vA)^{-1},&
 \lambda^2&=\frac{\pi}{8vA},\label{eq:target-constants}\\
 m_D(z)&=\lambda\bigl[\omega_D(z,A_+)-\omega_D(z,A_-)\bigr].&&&
 \label{eq:target-mean}
\end{align}
Here $\omega_D$ is harmonic measure and $A$ is the tangent-flux coefficient
defined in the cell construction. The stiffness is $vA$; no elementary
closed form for it is proposed.
\end{theorem}

\begin{theorem}\label{thm:main}
There are constants $A>0$, $\sigma>0$, and $\lambda\in(0,1/2]$, independent
of $D,a,b$, such that the model \eqref{eq:model} has
\[
 \gamma_\delta\Longrightarrow\mathrm{SLE}_4(D;a,b),\qquad
 \frac{h_\delta-\E h_\delta}{\sigma}
       \Longrightarrow\mathrm{GFF}_D
\]
in the stated curve metric and as random distributions, respectively.
The constants and limiting mean are
\begin{align}
 v&=2/\sqrt3,&\sigma^2&=(vA)^{-1},&
 \lambda^2&=\frac{\pi}{8vA},\label{eq:target-constants}\\
 m_D(z)&=\lambda\bigl[\omega_D(z,A_+)-\omega_D(z,A_-)\bigr].&&&
 \label{eq:target-mean}
\end{align}
Here $\omega_D$ is harmonic measure and $A$ is the tangent-flux coefficient
defined in the cell construction. The stiffness is $vA$; no elementary
closed form for it is proposed.
\end{theorem}

\begin{theorem}\label{thm:uniformization}
Let $M$ be a connected noncompact complex manifold of complex dimension
$n\geq1$. If $M$ admits a smooth complete K\"ahler metric with strictly
positive holomorphic bisectional curvature, then $M$ is biholomorphic
to $\C^n$.
\end{theorem}

\begin{theorem}[Universal energy minimality]\label{thm:universal}
Let $g:(0,\infty)\to[0,\infty)$ be smooth and completely monotone, meaning
that $(-1)^r g^{(r)}(t)\ge0$ for every integer $r\ge0$ and every $t>0$.
For every locally finite configuration $\mathcal C\subset\R^2$ of centered
disk density one, the following equality and inequality hold in the extended
nonnegative reals:
\begin{equation}\label{eq:main-inequality}
 E_g(\mathcal C)\ge
 \sum_{a\in A\setminus\{0\}}g(\abs a^2)=E_g(A).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
Let \(M\) be a complex von Neumann algebra and let \(k\geq2\).
Every \(f\in C_b^k(M,M)\) satisfying \(df=0\) has the form
\(f=dg\) for some \(g\in C_b^{k-1}(M,M)\).
Consequently \(H_b^k(M,M)=0\).
\end{theorem}

\begin{theorem}\label{thm:main}
Both \(\WL\) and \(\SubWL\) are \(\EXPTIME\)-complete under deterministic
polynomial-time many-one reductions.
\end{theorem}

\begin{theorem}\label{thm:main}
Let \(X\subset\PP^N_\C\) be a smooth complete intersection. Its ordinary, unreduced total descendant potential satisfies the Virasoro constraints in every genus and curve class, with arbitrary insertions from \(H^*(X;\C)\).
\end{theorem}

\begin{theorem}
\label{thm:main}
Let $B$ be a smooth connected projective variety over $\C$, and
let $E$ be an algebraic vector bundle of rank $r\geq2$ on $B$.
Let $X=\mathbb P_B(E)$ parametrize one-dimensional subspaces of
the fibers of $E$. Then
\[
                           \V(B)\ \Longrightarrow\ \V(X).
\]
\end{theorem}

\begin{theorem}[Weak Hessian bounds along every geodesic]
\label{weight:every-geodesic}
Let \((M,d,m)\) be a full-support \(\RCD(K,N)\) space,
where \(K\in\mathbb R\) and \(1<N<\infty\). Let
\(F\colon M\to\mathbb R\) be bounded and globally Lipschitz,
and let \(G\colon M\to\mathbb R\) be bounded and continuous.
Suppose that for every compactly supported \(g\in\Test(M)\)
and every nonnegative \(h\in\Lip_c(M)\),
\begin{equation}
\label{weight:hessian-assumption}
H_F(\nabla g,\nabla g)(h)
\le\int_M hG\Gamma(g)\dd m.
\end{equation}
Then every constant-speed minimizing geodesic
\(\sigma\colon[0,1]\to M\), of length \(\ell\), satisfies
\begin{equation}
\label{weight:curve-hessian}
(F\circ\sigma)''\le\ell^2G\circ\sigma
\qquad\text{in distributions on }(0,1).
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
The unit-speed billiard flow in every nondegenerate Euclidean triangle with
at least one angle irrational relative to \(\pi\) is weakly mixing for
normalized Liouville measure.
\end{theorem}

\begin{theorem}\label{thm:individual-to-strong}
Let \(C\) be a complex \(C^*\)-algebra satisfying \(\propP\).
For all \(a,b\in C_+\), \(c\in C\), and \(\varepsilon>0\), there are
\(s,t\in C\) such that
\begin{equation}\label{eq:main-diagonalization}
 \|s^*as-a\|<\varepsilon,\qquad
 \|t^*bt-b\|<\varepsilon,\qquad
 \|s^*ct\|<\varepsilon.
\end{equation}
Consequently \(C\) is strongly purely infinite.
\end{theorem}

\begin{theorem}\label{thm:main}
There exist a vocabulary \(\tau\) of eight binary relations, a fixed polynomial
\(p\), and a \(\CPT+\WSC\) sentence \((\Phi,p)\) with one occurrence of a WSC
operator such that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \((\Phi,p)\) has a Boolean value on every finite \(\tau\)-structure;
\item no \(\CPT\) sentence over \(\tau\) has the same true-model class.
\end{enumerate}
The \(\CPT\) sentences in \textup{(ii)} may use counting and hereditarily
finite sets of unrestricted finite rank.
\end{theorem}

\begin{theorem}\label{thm:main}
There exists a torsion-free word-hyperbolic group that is not residually finite.
\end{theorem}

\begin{theorem}[Quantitative sample lower bound]\label{thm:main}
Fix $s\in(0,1]$ and $0<c<1/(4\log2)$.  Along every sequence of instances $(n,q)$ with $n\to\infty$, $q\in(0,1)$, and $q^3\log n\to\infty$,
\begin{equation}\label{eq:main-bound}
 T_{q,s}(n)\ge n^{c\log(q^3\log n)}
\end{equation}
eventually.  All logarithms are natural.  In particular, for each fixed deletion probability $q\in(0,1)$ and fixed positive success probability $s$, the required sample number is $n^{\Omega(\log\log n)}$.
\end{theorem}

\begin{theorem}\label{thm:recognition}
Let $P$ be a finitely generated virtually polycyclic group, and let $H$ be any finitely generated group. If $H$ and $P$ are quasi-isometric, then $H$ is virtually polycyclic.
\end{theorem}

\begin{theorem}[Two infinite summands]\label{thm:main}
There do not exist two infinite sets $A,B\subseteq\N_0$ such that
$(A+B)\mathbin{\triangle}\mathcal P$ is finite.
\end{theorem}

\begin{theorem}[Ostmann's conjecture]\label{cor:ostmann}
If $A,B\subseteq\N_0$ satisfy $|A|,|B|\ge2$, then
$(A+B)\mathbin{\triangle}\mathcal P$ is infinite.
Equivalently, every finite modification of $\mathcal P$ is additively
indecomposable into two sets with at least two elements each.
\end{theorem}

\begin{theorem}\label{thm:main}
If $\deg F\le5$, the system \eqref{eq:original-system} has at most
two limit cycles in $\R^2$. Some members of this class have two
limit cycles. Thus its exact maximum is two.
\end{theorem}

\begin{theorem}[Uniform boundedness]\label{thm:uniform}
For each integer \(d\geq1\), there is a finite nonnegative integer \(B(d)\)
such that every real planar polynomial vector field of degree at most \(d\)
has at most \(B(d)\) limit cycles in the whole plane.
\end{theorem}
